export default JSON.parse("{\"workId\":\"han-fei-zi\",\"chapter\":{\"id\":\"han-fei-zi_ch-30\",\"workId\":\"han-fei-zi\",\"order\":30,\"title\":\"內儲說上\",\"difficulty\":4,\"estimatedMinutes\":22,\"passageIds\":[\"han-fei-zi_ch-30_p-1\",\"han-fei-zi_ch-30_p-2\",\"han-fei-zi_ch-30_p-3\",\"han-fei-zi_ch-30_p-4\",\"han-fei-zi_ch-30_p-5\",\"han-fei-zi_ch-30_p-6\",\"han-fei-zi_ch-30_p-7\",\"han-fei-zi_ch-30_p-8\",\"han-fei-zi_ch-30_p-9\",\"han-fei-zi_ch-30_p-10\",\"han-fei-zi_ch-30_p-11\",\"han-fei-zi_ch-30_p-12\",\"han-fei-zi_ch-30_p-13\",\"han-fei-zi_ch-30_p-14\",\"han-fei-zi_ch-30_p-15\",\"han-fei-zi_ch-30_p-16\",\"han-fei-zi_ch-30_p-17\",\"han-fei-zi_ch-30_p-18\",\"han-fei-zi_ch-30_p-19\",\"han-fei-zi_ch-30_p-20\",\"han-fei-zi_ch-30_p-21\",\"han-fei-zi_ch-30_p-22\",\"han-fei-zi_ch-30_p-23\",\"han-fei-zi_ch-30_p-24\",\"han-fei-zi_ch-30_p-25\",\"han-fei-zi_ch-30_p-26\",\"han-fei-zi_ch-30_p-27\",\"han-fei-zi_ch-30_p-28\",\"han-fei-zi_ch-30_p-29\",\"han-fei-zi_ch-30_p-30\",\"han-fei-zi_ch-30_p-31\",\"han-fei-zi_ch-30_p-32\",\"han-fei-zi_ch-30_p-33\",\"han-fei-zi_ch-30_p-34\",\"han-fei-zi_ch-30_p-35\",\"han-fei-zi_ch-30_p-36\",\"han-fei-zi_ch-30_p-37\",\"han-fei-zi_ch-30_p-38\",\"han-fei-zi_ch-30_p-39\",\"han-fei-zi_ch-30_p-40\",\"han-fei-zi_ch-30_p-41\",\"han-fei-zi_ch-30_p-42\",\"han-fei-zi_ch-30_p-43\",\"han-fei-zi_ch-30_p-44\",\"han-fei-zi_ch-30_p-45\",\"han-fei-zi_ch-30_p-46\",\"han-fei-zi_ch-30_p-47\",\"han-fei-zi_ch-30_p-48\",\"han-fei-zi_ch-30_p-49\",\"han-fei-zi_ch-30_p-50\",\"han-fei-zi_ch-30_p-51\",\"han-fei-zi_ch-30_p-52\",\"han-fei-zi_ch-30_p-53\",\"han-fei-zi_ch-30_p-54\",\"han-fei-zi_ch-30_p-55\",\"han-fei-zi_ch-30_p-56\",\"han-fei-zi_ch-30_p-57\",\"han-fei-zi_ch-30_p-58\",\"han-fei-zi_ch-30_p-59\",\"han-fei-zi_ch-30_p-60\",\"han-fei-zi_ch-30_p-61\",\"han-fei-zi_ch-30_p-62\",\"han-fei-zi_ch-30_p-63\",\"han-fei-zi_ch-30_p-64\",\"han-fei-zi_ch-30_p-65\",\"han-fei-zi_ch-30_p-66\",\"han-fei-zi_ch-30_p-67\",\"han-fei-zi_ch-30_p-68\",\"han-fei-zi_ch-30_p-69\",\"han-fei-zi_ch-30_p-70\",\"han-fei-zi_ch-30_p-71\",\"han-fei-zi_ch-30_p-72\",\"han-fei-zi_ch-30_p-73\",\"han-fei-zi_ch-30_p-74\",\"han-fei-zi_ch-30_p-75\",\"han-fei-zi_ch-30_p-76\",\"han-fei-zi_ch-30_p-77\"],\"tags\":[\"法家\",\"帝王術\",\"法術勢\"]},\"passages\":[{\"id\":\"han-fei-zi_ch-30_p-1\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":1,\"canonicalText\":\"主之所用也七術，所察也六微。七術：一曰、眾端參觀，二曰、必罰明威，三曰、信賞盡能，四曰、一聽責下，五曰、疑詔詭使，六曰、挾知而問，七曰、倒言反事。此七者，主之所用也。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-1_s-1\",\"han-fei-zi_ch-30_p-1_s-2\",\"han-fei-zi_ch-30_p-1_s-3\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"主的所用啊七御臣心術權謀，所察啊六微。七御臣心術權謀：一說道：、眾端參觀，二說道：、必刑罰制裁明威，三說道：、信賞賜恩惠盡能，四說道：、一聽責下，五說道：、疑詔詭使，六說道：、挾知而且問，七說道：、倒言反事。此七的人或事物，主的所用啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 1 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「主之所用也七術，所察也六微」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「主之所用也七術，所察也六微。七術：一曰、眾端參觀，二……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-2\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":2,\"canonicalText\":\"觀聽不參則誠不聞，聽有門戶則臣壅塞。其說在侏儒之夢見竈，哀公之稱莫眾而迷。故齊人見河伯，與惠子之言亡其半也。其患在豎牛之餓叔孫，而江乙之說荊俗也。嗣公欲治不知，故使有敵。是以明主推積鐵之類，而察一市之患。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-2_s-1\",\"han-fei-zi_ch-30_p-2_s-2\",\"han-fei-zi_ch-30_p-2_s-3\",\"han-fei-zi_ch-30_p-2_s-4\",\"han-fei-zi_ch-30_p-2_s-5\",\"han-fei-zi_ch-30_p-2_s-6\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"觀聽不參則誠不聞，聽有門戶則臣下僚屬壅塞。他的說在侏儒的夢見竈，哀公的稱莫眾而且迷。所以齊人見河伯，與惠子的言亡他的半啊。他的患在豎牛的餓叔孫，而且江乙的說荊俗啊。嗣公欲治不知，所以使有敵。是以明主推積鐵的類，而且察一市的患。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 2 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「觀聽不參則誠不聞，聽有門戶則臣壅塞」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「觀聽不參則誠不聞，聽有門戶則臣壅塞。其說在侏儒之夢見……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-3\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":3,\"canonicalText\":\"參觀一\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-3_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"參觀一。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 3 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「參觀一」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「參觀一」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-4\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":4,\"canonicalText\":\"愛多者則法不立，威寡者則下侵上。是以刑罰不必則禁令不行。其說在董子之行石邑，與子產之教遊吉也。故仲尼說隕霜，而殷法刑棄灰；將行去樂池，而公孫鞅重輕罪。是以麗水之金不守，而積澤之火不救。成歡以太仁弱齊國，卜皮以慈惠亡魏王。管仲知之，故斷死人。嗣公知之，故買胥靡。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-4_s-1\",\"han-fei-zi_ch-30_p-4_s-2\",\"han-fei-zi_ch-30_p-4_s-3\",\"han-fei-zi_ch-30_p-4_s-4\",\"han-fei-zi_ch-30_p-4_s-5\",\"han-fei-zi_ch-30_p-4_s-6\",\"han-fei-zi_ch-30_p-4_s-7\",\"han-fei-zi_ch-30_p-4_s-8\",\"han-fei-zi_ch-30_p-4_s-9\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"愛多的人或事物則國家法度法規不立，威寡的人或事物則下侵上。是以刑刑罰制裁不必則禁令不行。他的說在董子的行石邑，與子產的教遊吉啊。所以仲尼說隕霜，而且殷國家法度法規刑棄灰；將行去樂池，而且公孫鞅重輕罪。是以麗水的金不守，而且積澤的火不救。成歡以太仁弱齊國，卜皮以慈惠亡魏王。管仲知的，所以斷死人。嗣公知的，所以買胥靡。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 4 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「愛多者則法不立，威寡者則下侵上」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「愛多者則法不立，威寡者則下侵上。是以刑罰不必則禁令不……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-5\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":5,\"canonicalText\":\"必罰二\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-5_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"必刑罰制裁二。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 5 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「必罰二」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「必罰二」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-6\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":6,\"canonicalText\":\"賞譽薄而謾者，下不用也，賞譽厚而信者下輕死。其說在文子稱若獸鹿。故越王焚宮室，而吳起倚車轅，李悝斷訟以射，宋崇門以毀死。句踐知之，故式怒蛙。昭侯知之，故藏弊褲。厚賞之使人為賁、諸也，婦人之拾蠶，漁者之握鱣，是以效之。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-6_s-1\",\"han-fei-zi_ch-30_p-6_s-2\",\"han-fei-zi_ch-30_p-6_s-3\",\"han-fei-zi_ch-30_p-6_s-4\",\"han-fei-zi_ch-30_p-6_s-5\",\"han-fei-zi_ch-30_p-6_s-6\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"賞賜恩惠譽薄而且謾的人或事物，下不用啊，賞賜恩惠譽厚而且信的人或事物下輕死。他的說在文子稱若獸鹿。所以越王焚宮室，而且吳起倚車轅，李悝斷訟以射，宋崇門以毀死。句踐知的，所以式怒蛙。昭侯知的，所以藏弊褲。厚賞賜恩惠的使人為賁、諸啊，婦人的拾蠶，漁的人或事物的握鱣，是以效的。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 6 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「賞譽薄而謾者，下不用也，賞譽厚而信者下輕死」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「賞譽薄而謾者，下不用也，賞譽厚而信者下輕死。其說在文……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-7\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":7,\"canonicalText\":\"賞譽三\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-7_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"賞賜恩惠譽三。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 7 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「賞譽三」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「賞譽三」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-8\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":8,\"canonicalText\":\"一聽則智愚不分，責下則人臣不參。其說在索鄭與吹竽。其患在申子之以趙紹、韓沓為嘗試。故公子氾議割河東，而應侯謀弛上黨。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-8_s-1\",\"han-fei-zi_ch-30_p-8_s-2\",\"han-fei-zi_ch-30_p-8_s-3\",\"han-fei-zi_ch-30_p-8_s-4\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"一聽則智愚不分，責下則人臣下僚屬不參。他的說在索鄭與吹竽。他的患在申子的以趙紹、韓沓為嘗試。所以公子氾議割河東，而且應侯謀弛上黨。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 8 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一聽則智愚不分，責下則人臣不參」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一聽則智愚不分，責下則人臣不參。其說在索鄭與吹竽。其……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-9\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":9,\"canonicalText\":\"一聽四\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-9_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"一聽四。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 9 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一聽四」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一聽四」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-10\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":10,\"canonicalText\":\"數見久待而不任，姦則鹿散。使人問他則不鬻私。是以龐敬還公大夫，而戴讙詔視轀車。周主亡玉簪，商太宰論牛矢。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-10_s-1\",\"han-fei-zi_ch-30_p-10_s-2\",\"han-fei-zi_ch-30_p-10_s-3\",\"han-fei-zi_ch-30_p-10_s-4\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"數見久待而且不任，姦則鹿散。使人問他則不鬻私。是以龐敬還公大夫，而且戴讙詔視轀車。周主亡玉簪，商太宰論牛矢。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 10 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「數見久待而不任，姦則鹿散」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「數見久待而不任，姦則鹿散。使人問他則不鬻私。是以龐敬……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-11\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":11,\"canonicalText\":\"詭使五\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-11_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"詭使五。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 11 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「詭使五」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「詭使五」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-12\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":12,\"canonicalText\":\"挾智而問，則不智者至；深智一物，眾隱皆變。其說在昭侯之握一爪也。故必南門而三鄉得。周主索曲杖而群臣懼，卜皮事庶子，西門豹詳遺轄。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-12_s-1\",\"han-fei-zi_ch-30_p-12_s-2\",\"han-fei-zi_ch-30_p-12_s-3\",\"han-fei-zi_ch-30_p-12_s-4\",\"han-fei-zi_ch-30_p-12_s-5\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"挾智而且問，則不智的人或事物至；深智一物，眾隱皆變。他的說在昭侯的握一爪啊。所以必南門而且三鄉得。周主索曲杖而且群臣下僚屬懼，卜皮事庶子，西門豹詳遺轄。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 12 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「挾智而問，則不智者至」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「挾智而問，則不智者至；深智一物，眾隱皆變。其說在昭侯……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-13\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":13,\"canonicalText\":\"挾智六\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-13_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"挾智六。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 13 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「挾智六」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「挾智六」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-14\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":14,\"canonicalText\":\"倒言反事以嘗所疑則姦情得。故陽山謾樛豎，淖齒為秦使，齊人慾為亂，子之以白馬，子產離訟者，嗣公過關市。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-14_s-1\",\"han-fei-zi_ch-30_p-14_s-2\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"倒言反事以嘗所疑則姦情得。所以陽山謾樛豎，淖齒為秦使，齊人慾為亂，子的以白馬，子產離訟的人或事物，嗣公過關市。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 14 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「倒言反事以嘗所疑則姦情得」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「倒言反事以嘗所疑則姦情得。故陽山謾樛豎，淖齒為秦使，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-15\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":15,\"canonicalText\":\"倒言七\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-15_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"倒言七。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 15 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「倒言七」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「倒言七」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-16\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":16,\"canonicalText\":\"右經\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-16_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"右經。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 16 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「右經」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「右經」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-17\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":17,\"canonicalText\":\"說一\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-17_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說一。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 17 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「說一」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「說一」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-18\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":18,\"canonicalText\":\"衛靈公之時，彌子瑕有寵，專於衛國，侏儒有見公者曰：「臣之夢踐矣。」公曰：「何夢？」對曰：「夢見竈，為見公也。」公怒曰：「吾聞見人主者夢見日，奚為見寡人而夢見竈？」對曰：「夫日兼燭天下，一物不能當也。人君兼燭一國，一人不能壅也，故將見人主者夢見日。夫竈一人煬焉，則後人無從見矣。今或者一人、有煬君者乎？則臣雖夢見竈，不亦可乎！」\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-18_s-1\",\"han-fei-zi_ch-30_p-18_s-2\",\"han-fei-zi_ch-30_p-18_s-3\",\"han-fei-zi_ch-30_p-18_s-4\",\"han-fei-zi_ch-30_p-18_s-5\",\"han-fei-zi_ch-30_p-18_s-6\",\"han-fei-zi_ch-30_p-18_s-7\",\"han-fei-zi_ch-30_p-18_s-8\",\"han-fei-zi_ch-30_p-18_s-9\",\"han-fei-zi_ch-30_p-18_s-10\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"衛靈公的時，彌子瑕有寵，專於衛國，侏儒有見公的人或事物說道：臣下僚屬的夢踐矣。公說道：何夢？對說道：夢見竈，為見公啊。公怒說道：吾聞見人主的人或事物夢見日，奚為見寡人而且夢見竈？對說道：夫日兼燭天下，一物不能當啊。人君主統治者兼燭一國，一人不能壅啊，所以將見人主的人或事物夢見日。夫竈一人煬焉，則後人無從見矣。今或的人或事物一人、有煬君主統治者的人或事物乎？則臣下僚屬雖夢見竈，不亦可乎！\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 18 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「衛靈公之時，彌子瑕有寵，專於衛國，侏儒有見公者曰：「臣之夢踐矣」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「衛靈公之時，彌子瑕有寵，專於衛國，侏儒有見公者曰：「……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-19\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":19,\"canonicalText\":\"魯哀公問於孔子曰：「鄙諺曰：莫眾而迷。今寡人舉事，與群臣慮之，而國愈亂，其故何也？」孔子對曰：「明主之問臣，一人知之，一人不知也。如是者，明主在上，群臣直議於下。今群臣無不一辭同軌乎季孫者，舉魯國盡化為一，君雖問境內之人，猶不免於亂也。」\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-19_s-1\",\"han-fei-zi_ch-30_p-19_s-2\",\"han-fei-zi_ch-30_p-19_s-3\",\"han-fei-zi_ch-30_p-19_s-4\",\"han-fei-zi_ch-30_p-19_s-5\",\"han-fei-zi_ch-30_p-19_s-6\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"魯哀公問於孔子說道：鄙諺說道：莫眾而且迷。今寡人舉事，與群臣下僚屬慮的，而且國愈亂，他的所以何啊？孔子對說道：明主的問臣下僚屬，一人知的，一人不知啊。如是的人或事物，明主在上，群臣下僚屬直議於下。今群臣下僚屬無不一辭同軌乎季孫的人或事物，舉魯國盡化為一，君主統治者雖問境內的人，猶不免於亂啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 19 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「魯哀公問於孔子曰：「鄙諺曰：莫眾而迷」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「魯哀公問於孔子曰：「鄙諺曰：莫眾而迷。今寡人舉事，與……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-20\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":20,\"canonicalText\":\"一曰。晏子聘魯，哀公問曰：「語曰：莫三人而迷。今寡人與一國慮之，魯不免於亂何也？」晏子曰：「古之所謂莫三人而迷者，一人失之，二人得之，三人足以為眾矣，故曰莫三人而迷。今魯國之群臣以千百數，一言於季氏之私，人數非不眾，所言者一人也，安得三哉？」\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-20_s-1\",\"han-fei-zi_ch-30_p-20_s-2\",\"han-fei-zi_ch-30_p-20_s-3\",\"han-fei-zi_ch-30_p-20_s-4\",\"han-fei-zi_ch-30_p-20_s-5\",\"han-fei-zi_ch-30_p-20_s-6\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"一說道：。晏子聘魯，哀公問說道：語說道：莫三人而且迷。今寡人與一國慮的，魯不免於亂何啊？晏子說道：古的所謂莫三人而且迷的人或事物，一人失的，二人得的，三人足以為眾矣，因此韓絕不是子評論說道：莫三人而且迷。今魯國的群臣下僚屬以千百數，一言於季氏的私，人數絕不是不眾，所言的人或事物一人啊，安得三哉？\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 20 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。晏子聘魯，哀公問曰：「語曰：莫三人而迷。今寡人……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-21\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":21,\"canonicalText\":\"齊人有謂齊王曰：「河伯，大神也。王何不試與之遇乎？臣請使王遇之。」乃為壇場大水之上，而與王立之焉。有閒，大魚動，因曰：「此河伯。」\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-21_s-1\",\"han-fei-zi_ch-30_p-21_s-2\",\"han-fei-zi_ch-30_p-21_s-3\",\"han-fei-zi_ch-30_p-21_s-4\",\"han-fei-zi_ch-30_p-21_s-5\",\"han-fei-zi_ch-30_p-21_s-6\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"齊人有謂齊王說道：河伯，大神啊。王何不試與的遇乎？臣下僚屬請使王遇的。乃為壇場大水的上，而且與王立的焉。有閒，大魚動，因說道：此河伯。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 21 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「齊人有謂齊王曰：「河伯，大神也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「齊人有謂齊王曰：「河伯，大神也。王何不試與之遇乎？臣……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-22\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":22,\"canonicalText\":\"張儀欲以秦、韓與魏之勢伐齊、荊，而惠施欲以齊、荊偃兵。二人爭之，群臣左右皆為張子言，而以攻齊、荊為利，而莫為惠子言，王果聽張子，而以惠子言為不可。攻齊、荊事已定，惠子入見，王言曰：「先生毋言矣。攻齊、荊之事果利矣，一國盡以為然。」惠子因說：「不可不察也。夫齊、荊之事也誠利，一國盡以為利，是何智者之眾也？攻齊、荊之事誠不利，一國盡以為利，何愚者之眾也？凡謀者，疑也。疑也者，誠疑，以為可者半，以為不可者半。今一國盡以為可，是王亡半也。劫主者固亡其半者也。」\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-22_s-1\",\"han-fei-zi_ch-30_p-22_s-2\",\"han-fei-zi_ch-30_p-22_s-3\",\"han-fei-zi_ch-30_p-22_s-4\",\"han-fei-zi_ch-30_p-22_s-5\",\"han-fei-zi_ch-30_p-22_s-6\",\"han-fei-zi_ch-30_p-22_s-7\",\"han-fei-zi_ch-30_p-22_s-8\",\"han-fei-zi_ch-30_p-22_s-9\",\"han-fei-zi_ch-30_p-22_s-10\",\"han-fei-zi_ch-30_p-22_s-11\",\"han-fei-zi_ch-30_p-22_s-12\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"張儀欲以秦、韓與魏的至高權力威勢伐齊、荊，而且惠施欲以齊、荊偃兵。二人爭的，群臣下僚屬左右皆為張子言，而且以攻齊、荊為利，而且莫為惠子言，王果聽張子，而且以惠子言為不可。攻齊、荊事已定，惠子入見，王言說道：先生毋言矣。攻齊、荊的事果利矣，一國盡以為然。惠子因說：不可不察啊。夫齊、荊的事啊誠利，一國盡以為利，是何智的人或事物的眾啊？攻齊、荊的事誠不利，一國盡以為利，何愚的人或事物的眾啊？凡謀的人或事物，疑啊。疑啊的人或事物，誠疑，以為可的人或事物半，以為不可的人或事物半。今一國盡以為可，是王亡半啊。劫主的人或事物固亡他的半的人或事物啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 22 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「張儀欲以秦、韓與魏之勢伐齊、荊，而惠施欲以齊、荊偃兵」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「張儀欲以秦、韓與魏之勢伐齊、荊，而惠施欲以齊、荊偃兵……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-23\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":23,\"canonicalText\":\"叔孫相魯，貴而主斷。其所愛者曰豎牛，亦擅用叔孫之令。叔孫有子曰壬，豎牛妒而欲殺之，因與壬遊於魯君所，魯君賜之玉環，壬拜受之而不敢佩，使豎牛請之叔孫，豎牛欺之曰：「吾已為爾請之矣，使爾佩之。」壬因佩之，豎牛因謂叔孫：「何不見壬於君乎？」叔孫曰：「孺子何足見也。」豎牛曰：「壬固已數見於君矣。君賜之玉環，壬已佩之矣。」叔孫召壬見之，而果佩之，叔孫怒而殺壬。壬兄曰丙，豎牛又妒而欲殺之，叔孫為丙鑄鐘，鐘成，丙不敢擊，使豎牛請之叔孫，豎牛不為請，又欺之曰：「吾已為爾請之矣。使爾擊之。」丙因擊之，叔孫聞之曰：「丙不請而擅擊鐘。」怒而逐之。丙出走齊，居一年，豎牛為謝叔孫，叔孫使豎牛召之，又不召而報之曰：「吾已召之矣，丙怒甚，不肯來。」叔孫大怒，使人殺之。二子已死，叔孫有病，豎牛因獨養之而去左右，不內人，曰：「叔孫不欲聞人聲。」因不食而餓殺。叔孫已死，豎牛因不發喪也，徙其府庫重寶空之而奔齊。夫聽所信之言，而子父為人僇，此不參之患也。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-23_s-1\",\"han-fei-zi_ch-30_p-23_s-2\",\"han-fei-zi_ch-30_p-23_s-3\",\"han-fei-zi_ch-30_p-23_s-4\",\"han-fei-zi_ch-30_p-23_s-5\",\"han-fei-zi_ch-30_p-23_s-6\",\"han-fei-zi_ch-30_p-23_s-7\",\"han-fei-zi_ch-30_p-23_s-8\",\"han-fei-zi_ch-30_p-23_s-9\",\"han-fei-zi_ch-30_p-23_s-10\",\"han-fei-zi_ch-30_p-23_s-11\",\"han-fei-zi_ch-30_p-23_s-12\",\"han-fei-zi_ch-30_p-23_s-13\",\"han-fei-zi_ch-30_p-23_s-14\",\"han-fei-zi_ch-30_p-23_s-15\",\"han-fei-zi_ch-30_p-23_s-16\",\"han-fei-zi_ch-30_p-23_s-17\",\"han-fei-zi_ch-30_p-23_s-18\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"叔孫相魯，貴而且主斷。他的所愛的人或事物說道：豎牛，亦擅用叔孫的令。叔孫有子說道：壬，豎牛妒而且欲殺的，因與壬遊於魯君主統治者所，魯君主統治者賜的玉環，壬拜受的而且不敢佩，使豎牛請的叔孫，豎牛欺的說道：吾已為爾請的矣，使爾佩的。壬因佩的，豎牛因謂叔孫：何不見壬於君主統治者乎？叔孫說道：孺子何足見啊。豎牛說道：壬固已數見於君主統治者矣。君主統治者賜的玉環，壬已佩的矣。叔孫召壬見的，而且果佩的，叔孫怒而且殺壬。壬兄說道：丙，豎牛又妒而且欲殺的，叔孫為丙鑄鐘，鐘成，丙不敢擊，使豎牛請的叔孫，豎牛不為請，又欺的說道：吾已為爾請的矣。使爾擊的。丙因擊的，叔孫聞的說道：丙不請而且擅擊鐘。怒而且逐的。丙出走齊，居一年，豎牛為謝叔孫，叔孫使豎牛召的，又不召而且報的說道：吾已召的矣，丙怒甚，不肯來。叔孫大怒，使人殺的。二子已死，叔孫有病，豎牛因獨養的而且去左右，不內人，說道：叔孫不欲聞人聲。因不食而且餓殺。叔孫已死，豎牛因不發喪啊，徙他的府庫重寶空的而且奔齊。夫聽所信的言，而且子父為人僇，此不參的患啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 23 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「叔孫相魯，貴而主斷」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「叔孫相魯，貴而主斷。其所愛者曰豎牛，亦擅用叔孫之令。……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-24\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":24,\"canonicalText\":\"江乙為魏王使荊，謂荊王曰：「臣入王之境內，聞王之國俗曰：君子不蔽人之美，不言人之惡，誠有之乎？」王曰：「有之。」「然則若白公之亂，得庶無危乎！誠得如此，臣免死罪矣。」\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-24_s-1\",\"han-fei-zi_ch-30_p-24_s-2\",\"han-fei-zi_ch-30_p-24_s-3\",\"han-fei-zi_ch-30_p-24_s-4\",\"han-fei-zi_ch-30_p-24_s-5\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"江乙為魏王使荊，謂荊王說道：臣下僚屬入王的境內，聞王的國俗說道：君主統治者子不蔽人的美，不言人的惡，誠有的乎？王說道：有的。然則若白公的亂，得庶無危乎！誠得如此，臣下僚屬免死罪矣。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 24 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「江乙為魏王使荊，謂荊王曰：「臣入王之境內，聞王之國俗曰：君子不蔽人之美，不言人之惡，誠有之乎」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「江乙為魏王使荊，謂荊王曰：「臣入王之境內，聞王之國俗……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-25\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":25,\"canonicalText\":\"衛嗣君重如耳，愛世姬，而恐其皆因其愛重以壅己也，乃貴薄疑以敵如耳，尊魏姬以耦世姬，曰：「以是相參也。」嗣君知欲無壅，而未得其術也。夫不使賤議貴，下必坐上，而必待勢重之鈞也，而後敢相議，則是益樹壅塞之臣也。嗣君之壅乃始。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-25_s-1\",\"han-fei-zi_ch-30_p-25_s-2\",\"han-fei-zi_ch-30_p-25_s-3\",\"han-fei-zi_ch-30_p-25_s-4\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"衛嗣君主統治者重如耳，愛世姬，而且恐他的皆因他的愛重以壅己啊，乃貴薄疑以敵如耳，尊魏姬以耦世姬，說道：以是相參啊。嗣君主統治者知欲無壅，而且未得他的御臣心術權謀啊。夫不使賤議貴，下必坐上，而且必待至高權力威勢重的鈞啊，而且後敢相議，則是益樹壅塞的臣下僚屬啊。嗣君主統治者的壅乃始。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 25 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「衛嗣君重如耳，愛世姬，而恐其皆因其愛重以壅己也，乃貴薄疑以敵如耳，尊魏姬以耦世姬，曰：「以是相參也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「衛嗣君重如耳，愛世姬，而恐其皆因其愛重以壅己也，乃貴……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-26\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":26,\"canonicalText\":\"夫矢來有鄉，則積鐵以備一鄉；矢來無鄉，則為鐵室以盡備之。備之則體不傷。故彼以盡備之不傷，此以盡敵之無姦也。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-26_s-1\",\"han-fei-zi_ch-30_p-26_s-2\",\"han-fei-zi_ch-30_p-26_s-3\",\"han-fei-zi_ch-30_p-26_s-4\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"夫矢來有鄉，則積鐵以備一鄉；矢來無鄉，則為鐵室以盡備的。備的則體不傷。所以彼以盡備的不傷，此以盡敵的無姦啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 26 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「夫矢來有鄉，則積鐵以備一鄉」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「夫矢來有鄉，則積鐵以備一鄉；矢來無鄉，則為鐵室以盡備……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-27\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":27,\"canonicalText\":\"龐恭與太子質於邯鄲，謂魏王曰：「今一人言市有虎，王信之乎？」曰：「不信。」「二人言市有虎，王信之乎？」曰：「不信。」「三人言市有虎，王信之乎？」王曰：「寡人信之。」龐恭曰：「夫市之無虎也明矣，然而三人言而成虎。今邯鄲之去魏也遠於市，議臣者過於三人，願王察之。」龐恭從邯鄲反，竟不得見。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-27_s-1\",\"han-fei-zi_ch-30_p-27_s-2\",\"han-fei-zi_ch-30_p-27_s-3\",\"han-fei-zi_ch-30_p-27_s-4\",\"han-fei-zi_ch-30_p-27_s-5\",\"han-fei-zi_ch-30_p-27_s-6\",\"han-fei-zi_ch-30_p-27_s-7\",\"han-fei-zi_ch-30_p-27_s-8\",\"han-fei-zi_ch-30_p-27_s-9\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"龐恭與太子質於邯鄲，謂魏王說道：今一人言市有虎，王信的乎？說道：不信。二人言市有虎，王信的乎？三人言市有虎，王信的乎？王說道：寡人信的。龐恭說道：夫市的無虎啊明矣，然而且三人言而且成虎。今邯鄲的去魏啊遠於市，議臣下僚屬的人或事物過於三人，願王察的。龐恭從邯鄲反，竟不得見。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 27 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「龐恭與太子質於邯鄲，謂魏王曰：「今一人言市有虎，王信之乎」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「龐恭與太子質於邯鄲，謂魏王曰：「今一人言市有虎，王信……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-28\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":28,\"canonicalText\":\"說二\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-28_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說二。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 28 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「說二」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「說二」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-29\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":29,\"canonicalText\":\"董閼於為趙上地守，行石邑山中，澗深，峭如牆，深百仞，因問其旁鄉左右曰：「人嘗有入此者乎？」對曰：「無有。」曰：「嬰兒癡聾狂悖之人嘗有入此者乎？」對曰：「無有。」「牛馬犬彘嘗有入此者乎？」對曰：「無有。」董閼於喟然太息曰：「吾能治矣。使吾法之無赦，猶入澗之必死也，則人莫之敢犯也，何為不治？」\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-29_s-1\",\"han-fei-zi_ch-30_p-29_s-2\",\"han-fei-zi_ch-30_p-29_s-3\",\"han-fei-zi_ch-30_p-29_s-4\",\"han-fei-zi_ch-30_p-29_s-5\",\"han-fei-zi_ch-30_p-29_s-6\",\"han-fei-zi_ch-30_p-29_s-7\",\"han-fei-zi_ch-30_p-29_s-8\",\"han-fei-zi_ch-30_p-29_s-9\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"董閼於擔任趙國上地的郡守，有一次巡視石邑山中，看到一條山澗深不見底，兩側陡峭如牆，深達百丈。於是他問旁邊的鄉民說：曾經有人掉進去過嗎？鄉民回答：沒有。他又問：嬰兒、癡呆、耳聾、發狂的人曾經掉進去過嗎？他再問：牛馬狗豬曾經掉進去過嗎？鄉民回答：也沒有。董閼於長嘆一聲說：我懂得該如何治理了！如果我制定法律絕不寬恕罪犯，就像掉進這山澗必定會死一樣，那麼就沒有人敢觸犯法律了，這樣國家怎麼會治理不好呢？\",\"analysis\":\"【訓詁與名物】「董閼於」為春秋戰國時期晉國（後屬趙）的名臣。「百仞」為虛指，極言其深，古時八尺為一仞。「狂悖」指精神失常或行為悖理的人。「彘」是豬的古稱。\\\\n【章法與結構】本段以一則生動的寓言故事來闡述法家理念。先描繪山澗的深邃危險，接著透過董閼於與鄉民的一連串問答，排除了任何生物掉入的可能性，最後由董閼於的感嘆點出主旨：以深澗必死之理，喻嚴刑峻罰之效，結構緊湊，設喻巧妙。\\\\n【思想與義理】這段故事精準傳達了法家「重罰以去罰」的核心思想。韓非子認為，法律的威懾力不在於教化，而在於其不可違逆的必然性與嚴酷性。就像深澗因為「入之必死」，所以連無知的嬰兒禽獸都不會掉進去；同樣地，法律若能做到「犯法必懲，絕不寬恕」，人民自然不敢違法，社會秩序便能輕易建立。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-30\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":30,\"canonicalText\":\"子產相鄭，病將死，謂遊吉曰：「我死後，子必用鄭，必以嚴蒞人。夫火形嚴，故人鮮灼；水形懦，人多溺。子必嚴子之形，無令溺子之懦。」故子產死，遊吉不肯嚴形，鄭少年相率為盜，處於雚澤，將遂以為鄭禍。遊吉率車騎與戰，一日一夜，僅能剋之。遊吉喟然歎曰：「吾蚤行夫子之教，必不悔至於此矣。」\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-30_s-1\",\"han-fei-zi_ch-30_p-30_s-2\",\"han-fei-zi_ch-30_p-30_s-3\",\"han-fei-zi_ch-30_p-30_s-4\",\"han-fei-zi_ch-30_p-30_s-5\",\"han-fei-zi_ch-30_p-30_s-6\",\"han-fei-zi_ch-30_p-30_s-7\",\"han-fei-zi_ch-30_p-30_s-8\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"子產相鄭，病將死，謂遊吉說道：我死後，子必用鄭，必以嚴蒞人。夫火形嚴，所以人鮮灼；水形懦，人多溺。子必嚴子的形，無令溺子的懦。所以子產死，遊吉不肯嚴形，鄭少年相率為盜，處於雚澤，將遂以為鄭禍。遊吉率車騎與戰，一日一夜，僅能剋的。遊吉喟然歎說道：吾蚤行夫子的教，必不悔至於此矣。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 30 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「子產相鄭，病將死，謂遊吉曰：「我死後，子必用鄭，必以嚴蒞人」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「子產相鄭，病將死，謂遊吉曰：「我死後，子必用鄭，必以……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-31\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":31,\"canonicalText\":\"魯哀公問於仲尼曰：「春秋之記曰：冬十二月霣霜不殺菽，何為記此？」仲尼對曰：「此言可以殺而不殺也。夫宜殺而不殺，桃李冬實。天失道，草木猶犯幹之，而況於人君乎？」\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-31_s-1\",\"han-fei-zi_ch-30_p-31_s-2\",\"han-fei-zi_ch-30_p-31_s-3\",\"han-fei-zi_ch-30_p-31_s-4\",\"han-fei-zi_ch-30_p-31_s-5\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"魯哀公問於仲尼說道：春秋的記說道：冬十二月霣霜不殺菽，何為記此？仲尼對說道：此言可以殺而且不殺啊。夫宜殺而且不殺，桃李冬實。天失道，草木猶犯幹的，而且況於人君主統治者乎？\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 31 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「魯哀公問於仲尼曰：「春秋之記曰：冬十二月霣霜不殺菽，何為記此」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「魯哀公問於仲尼曰：「春秋之記曰：冬十二月霣霜不殺菽，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-32\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":32,\"canonicalText\":\"殷之法刑棄灰於街者，子貢以為重，問之仲尼，仲尼曰：「知治之道也。夫棄灰於街必掩人，掩人人必怒，怒則鬥，鬥必三族相殘也。此殘三族之道也，雖刑之可也。且夫重罰者，人之所惡也，而無棄灰，人之所易也。使人行之所易，而無離所惡，此治之道。」\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-32_s-1\",\"han-fei-zi_ch-30_p-32_s-2\",\"han-fei-zi_ch-30_p-32_s-3\",\"han-fei-zi_ch-30_p-32_s-4\",\"han-fei-zi_ch-30_p-32_s-5\",\"han-fei-zi_ch-30_p-32_s-6\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"殷的國家法度法規刑棄灰於街的人或事物，子貢以為重，問的仲尼，仲尼說道：知治的道啊。夫棄灰於街必掩人，掩人人必怒，怒則鬥，鬥必三族相殘啊。此殘三族的道啊，雖刑的可啊。再的人或事物況且重刑罰制裁的人或事物，人的所惡啊，而且無棄灰，人的所易啊。使人行的所易，而且無離所惡，此治的道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 32 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「殷之法刑棄灰於街者，子貢以為重，問之仲尼，仲尼曰：「知治之道也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「殷之法刑棄灰於街者，子貢以為重，問之仲尼，仲尼曰：「……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-33\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":33,\"canonicalText\":\"一曰。殷之法，棄灰於公道者斷其手，子貢曰：「棄灰之罪輕，斷手之罰重，古人何太毅也？」曰：「無棄灰所易也，斷手所惡也，行所易不關所惡，古人以為易，故行之。」\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-33_s-1\",\"han-fei-zi_ch-30_p-33_s-2\",\"han-fei-zi_ch-30_p-33_s-3\",\"han-fei-zi_ch-30_p-33_s-4\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"一說道：。殷的國家法度法規，棄灰於公道的人或事物斷他的手，子貢說道：棄灰的罪輕，斷手的刑罰制裁重，古人何太毅啊？說道：無棄灰所易啊，斷手所惡啊，行所易不關所惡，古人以為易，所以行的。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 33 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。殷之法，棄灰於公道者斷其手，子貢曰：「棄灰之罪……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-34\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":34,\"canonicalText\":\"中山之相樂池以車百乘使趙，選其客之有智能者以為將行，中道而亂，樂池曰：「吾以公為有智，而使公為將行，今中道而亂何也？」客因辭而去曰：「公不知治，有威足以服人，而利足以勸之，故能治之。今臣，君之少客也。夫從少正長，從賤治貴，而不得操其利害之柄以制之，此所以亂也。嘗試使臣彼之善者我能以為卿相，彼不善者我得以斬其首，何故而不治？」\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-34_s-1\",\"han-fei-zi_ch-30_p-34_s-2\",\"han-fei-zi_ch-30_p-34_s-3\",\"han-fei-zi_ch-30_p-34_s-4\",\"han-fei-zi_ch-30_p-34_s-5\",\"han-fei-zi_ch-30_p-34_s-6\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"中山的相樂池以車百乘使趙，選他的客的有智能的人或事物以為將行，中道而且亂，樂池說道：吾以公為有智，而且使公為將行，今中道而且亂何啊？客因辭而且去說道：公不知治，有威足以服人，而且利足以勸的，所以能治的。今臣下僚屬，君主統治者的少客啊。夫從少正長，從賤治貴，而且不得操他的利害的柄以制的，此所以亂啊。嘗試使臣下僚屬彼的善的人或事物我能以為卿相，彼不善的人或事物我得以斬他的首，何所以而且不治？\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 34 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「中山之相樂池以車百乘使趙，選其客之有智能者以為將行，中道而亂，樂池曰：「吾以公為有智，而使公為將行，今中道而亂何也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「中山之相樂池以車百乘使趙，選其客之有智能者以為將行，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-35\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":35,\"canonicalText\":\"公孫鞅之法也重輕罪。重罪者人之所難犯也，而小過者人之所易去也，使人去其所易無離其所難，此治之道。夫小過不生，大罪不至，是人無罪而亂不生也。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-35_s-1\",\"han-fei-zi_ch-30_p-35_s-2\",\"han-fei-zi_ch-30_p-35_s-3\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"公孫鞅的國家法度法規啊重輕罪。重罪的人或事物人的所難犯啊，而且小過的人或事物人的所易去啊，使人去他的所易無離他的所難，此治的道。夫小過不生，大罪不至，是人無罪而且亂不生啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 35 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「公孫鞅之法也重輕罪」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「公孫鞅之法也重輕罪。重罪者人之所難犯也，而小過者人之……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-36\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":36,\"canonicalText\":\"一曰。公孫鞅曰：「行刑重其輕者，輕者不至，重者不來，是謂以刑去刑。」\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-36_s-1\",\"han-fei-zi_ch-30_p-36_s-2\",\"han-fei-zi_ch-30_p-36_s-3\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"一說道：。公孫鞅說道：行刑重他的輕的人或事物，輕的人或事物不至，重的人或事物不來，是謂以刑去刑。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 36 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。公孫鞅曰：「行刑重其輕者，輕者不至，重者不來，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-37\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":37,\"canonicalText\":\"荊南之地、麗水之中生金，人多竊採金，採金之禁，得而輒辜磔於市，甚眾，壅離其水也，而人竊金不止。夫罪莫重辜磔於市，猶不止者，不必得也。故今有於此，曰：「予汝天下而殺汝身」，庸人不為也。夫有天下，大利也，猶不為者，知必死。故不必得也，則雖辜磔，竊金不止；知必死，則天下不為也。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-37_s-1\",\"han-fei-zi_ch-30_p-37_s-2\",\"han-fei-zi_ch-30_p-37_s-3\",\"han-fei-zi_ch-30_p-37_s-4\",\"han-fei-zi_ch-30_p-37_s-5\",\"han-fei-zi_ch-30_p-37_s-6\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"荊南的地、麗水的中生金，人多竊採金，採金的禁，得而且輒辜磔於市，甚眾，壅離他的水啊，而且人竊金不止。夫罪莫重辜磔於市，猶不止的人或事物，不必得啊。所以今有於此，說道：予汝天下而且殺汝身，庸人不為啊。夫有天下，大利啊，猶不為的人或事物，知必死。所以不必得啊，則雖辜磔，竊金不止；知必死，則天下不為啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 37 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「荊南之地、麗水之中生金，人多竊採金，採金之禁，得而輒辜磔於市，甚眾，壅離其水也，而人竊金不止」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「荊南之地、麗水之中生金，人多竊採金，採金之禁，得而輒……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-38\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":38,\"canonicalText\":\"魯人燒積澤，天北風，火南倚，恐燒國，哀公懼，自將眾趣救火，左右無人，盡逐獸而火不救，乃召問仲尼，仲尼曰：「夫逐獸者樂而無罰，救火者苦而無賞，此火之所以無救也。」哀公曰：「善。」仲尼曰：「事急，不及以賞，救火者盡賞之，則國不足以賞於人，請徒行罰。」哀公曰：「善。」於是仲尼乃下令曰：「不救火者比降北之罪，逐獸者比入禁之罪。」令下未遍而火已救矣。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-38_s-1\",\"han-fei-zi_ch-30_p-38_s-2\",\"han-fei-zi_ch-30_p-38_s-3\",\"han-fei-zi_ch-30_p-38_s-4\",\"han-fei-zi_ch-30_p-38_s-5\",\"han-fei-zi_ch-30_p-38_s-6\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"魯人燒積澤，天北風，火南倚，恐燒國，哀公懼，自將眾趣救火，左右無人，盡逐獸而且火不救，乃召問仲尼，仲尼說道：夫逐獸的人或事物樂而且無刑罰制裁，救火的人或事物苦而且無賞賜恩惠，此火的所以無救啊。哀公說道：善。仲尼說道：事急，不及以賞賜恩惠，救火的人或事物盡賞賜恩惠的，則國不足以賞賜恩惠於人，請徒行刑罰制裁。於是仲尼乃下令說道：不救火的人或事物比降北的罪，逐獸的人或事物比入禁的罪。令下未遍而且火已救矣。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 38 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「魯人燒積澤，天北風，火南倚，恐燒國，哀公懼，自將眾趣救火，左右無人，盡逐獸而火不救，乃召問仲尼，仲尼曰：「夫逐獸者樂而無罰，救火者苦而無賞，此火之所以無救也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「魯人燒積澤，天北風，火南倚，恐燒國，哀公懼，自將眾趣……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-39\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":39,\"canonicalText\":\"成驩謂齊王曰：「王太仁，太不忍人。」王曰：「太仁、太不忍人，非善名邪？」對曰：「此人臣之善也，非人主之所行也。夫人臣必仁而後可與謀，不忍人而後可近也。不仁則不可與謀，忍人則不可近也。」王曰：「然則寡人安所太仁、安不忍人？」對曰：「王太仁於薛公，而太不忍於諸田。太仁薛公則大臣無重，太不忍諸田則父兄犯法。大臣無重則兵弱於外，父兄犯法則政亂於內。兵弱於外、政亂於內，此亡國之本也。」\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-39_s-1\",\"han-fei-zi_ch-30_p-39_s-2\",\"han-fei-zi_ch-30_p-39_s-3\",\"han-fei-zi_ch-30_p-39_s-4\",\"han-fei-zi_ch-30_p-39_s-5\",\"han-fei-zi_ch-30_p-39_s-6\",\"han-fei-zi_ch-30_p-39_s-7\",\"han-fei-zi_ch-30_p-39_s-8\",\"han-fei-zi_ch-30_p-39_s-9\",\"han-fei-zi_ch-30_p-39_s-10\",\"han-fei-zi_ch-30_p-39_s-11\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"成驩謂齊王說道：王太仁，太不忍人。王說道：太仁、太不忍人，絕不是善名邪？對說道：此人臣下僚屬的善啊，絕不是人主的所行啊。夫人臣下僚屬必仁而且後可與謀，不忍人而且後可近啊。不仁則不可與謀，忍人則不可近啊。王說道：然則寡人安所太仁、安不忍人？對說道：王太仁於薛公，而且太不忍於諸田。太仁薛公則大臣下僚屬無重，太不忍諸田則父兄犯國家法度法規。大臣下僚屬無重則兵弱於外，父兄犯國家法度法規則政亂於內。兵弱於外、政亂於內，此亡國的本啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 39 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「成驩謂齊王曰：「王太仁，太不忍人」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「成驩謂齊王曰：「王太仁，太不忍人。」王曰：「太仁、太……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-40\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":40,\"canonicalText\":\"魏惠王謂卜皮曰：「子聞寡人之聲聞亦何如焉？」對曰：「臣聞王之慈惠也。」王欣然喜曰：「然則功且安至？」對曰：「王之功至於亡。」王曰：「慈惠，行善也，行之而亡何也？」卜皮對曰：「夫慈者不忍，而惠者好與也。不忍則不誅有過，好予則不待有功而賞。有過不罪，無功受賞，雖亡不亦可乎？」\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-40_s-1\",\"han-fei-zi_ch-30_p-40_s-2\",\"han-fei-zi_ch-30_p-40_s-3\",\"han-fei-zi_ch-30_p-40_s-4\",\"han-fei-zi_ch-30_p-40_s-5\",\"han-fei-zi_ch-30_p-40_s-6\",\"han-fei-zi_ch-30_p-40_s-7\",\"han-fei-zi_ch-30_p-40_s-8\",\"han-fei-zi_ch-30_p-40_s-9\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"魏惠王謂卜皮說道：子聞寡人的聲聞亦何如焉？對說道：臣下僚屬聞王的慈惠啊。王欣然喜說道：然則功且安至？對說道：王的功至於亡。王說道：慈惠，行善啊，行的而且亡何啊？卜皮對說道：夫慈的人或事物不忍，而且惠的人或事物好與啊。不忍則不誅有過，好予則不待有功而且賞賜恩惠。有過不罪，無功受賞賜恩惠，雖亡不亦可乎？\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 40 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「魏惠王謂卜皮曰：「子聞寡人之聲聞亦何如焉」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「魏惠王謂卜皮曰：「子聞寡人之聲聞亦何如焉？」對曰：「……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-41\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":41,\"canonicalText\":\"齊國好厚葬，布帛盡於衣衾，材木盡於棺槨，桓公患之，以告管仲曰：「布帛盡則無以為蔽，材木盡則無以為守備，而人厚葬之不休，禁之奈何？」管仲對曰：「凡人之有為也，非名之則利之也。」於是乃下令曰：「棺槨過度者戮其屍，罪夫當喪者。」夫戮死無名，罪當喪者無利，人何故為之也？\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-41_s-1\",\"han-fei-zi_ch-30_p-41_s-2\",\"han-fei-zi_ch-30_p-41_s-3\",\"han-fei-zi_ch-30_p-41_s-4\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"齊國好厚葬，布帛盡於衣衾，材木盡於棺槨，桓公患的，以告管仲說道：布帛盡則無以為蔽，材木盡則無以為守備，而且人厚葬的不休，禁的奈何？管仲對說道：凡人的有為啊，絕不是名的則利的啊。於是乃下令說道：棺槨過度的人或事物戮他的屍，罪夫當喪的人或事物。夫戮死無名，罪當喪的人或事物無利，人何所以為的啊？\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 41 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「齊國好厚葬，布帛盡於衣衾，材木盡於棺槨，桓公患之，以告管仲曰：「布帛盡則無以為蔽，材木盡則無以為守備，而人厚葬之不休，禁之奈何」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「齊國好厚葬，布帛盡於衣衾，材木盡於棺槨，桓公患之，以……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-42\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":42,\"canonicalText\":\"衛嗣君之時，有胥靡逃之魏，因為襄王之後治病，衛嗣君聞之，使人請以五十金買之，五反而魏王不予，乃以左氏易之。群臣左右諫曰：「夫以一都買胥靡可乎？」王曰：「非子之所知也。夫治無小而亂無大，法不立而誅不必，雖有十左氏無益也。法立而誅必，雖失十左氏無害也。」魏王聞之曰：「主欲治而不聽之，不祥。」因載而往，徒獻之。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-42_s-1\",\"han-fei-zi_ch-30_p-42_s-2\",\"han-fei-zi_ch-30_p-42_s-3\",\"han-fei-zi_ch-30_p-42_s-4\",\"han-fei-zi_ch-30_p-42_s-5\",\"han-fei-zi_ch-30_p-42_s-6\",\"han-fei-zi_ch-30_p-42_s-7\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"衛嗣君主統治者的時，有胥靡逃的魏，因為襄王的後治病，衛嗣君主統治者聞的，使人請以五十金買的，五反而且魏王不予，乃以左氏易的。群臣下僚屬左右諫說道：夫以一都買胥靡可乎？王說道：絕不是子的所知啊。夫治無小而且亂無大，國家法度法規不立而且誅不必，雖有十左氏無益啊。國家法度法規立而且誅必，雖失十左氏無害啊。魏王聞的說道：主欲治而且不聽的，不祥。因載而且往，徒獻的。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 42 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「衛嗣君之時，有胥靡逃之魏，因為襄王之後治病，衛嗣君聞之，使人請以五十金買之，五反而魏王不予，乃以左氏易之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「衛嗣君之時，有胥靡逃之魏，因為襄王之後治病，衛嗣君聞……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-43\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":43,\"canonicalText\":\"說三\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-43_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說三。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 43 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「說三」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「說三」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-44\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":44,\"canonicalText\":\"齊王問於文子曰：「治國何如？」對曰：「夫賞罰之為道，利器也。君固握之，不可以示人。若如臣者，猶獸鹿也，唯薦草而就。」\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-44_s-1\",\"han-fei-zi_ch-30_p-44_s-2\",\"han-fei-zi_ch-30_p-44_s-3\",\"han-fei-zi_ch-30_p-44_s-4\",\"han-fei-zi_ch-30_p-44_s-5\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"齊王問於文子說道：治國何如？對說道：夫賞賜恩惠刑罰制裁的為道，利器啊。君主統治者固握的，不可以示人。若如臣下僚屬的人或事物，猶獸鹿啊，唯薦草而且就。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 44 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「齊王問於文子曰：「治國何如」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「齊王問於文子曰：「治國何如？」對曰：「夫賞罰之為道，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-45\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":45,\"canonicalText\":\"越王問於大夫文種曰：「吾欲伐吳可乎？」對曰：「可矣。吾賞厚而信，罰嚴而必。君欲知之，何不試焚宮室？」於是遂焚宮室，人莫救之，乃下令曰：「人之救火者，死，比死敵之賞。救火而不死者，比勝敵之賞。不救火者，比降北之罪。」人塗其體、被濡衣而走火者，左三千人，右三千人。此知必勝之勢也。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-45_s-1\",\"han-fei-zi_ch-30_p-45_s-2\",\"han-fei-zi_ch-30_p-45_s-3\",\"han-fei-zi_ch-30_p-45_s-4\",\"han-fei-zi_ch-30_p-45_s-5\",\"han-fei-zi_ch-30_p-45_s-6\",\"han-fei-zi_ch-30_p-45_s-7\",\"han-fei-zi_ch-30_p-45_s-8\",\"han-fei-zi_ch-30_p-45_s-9\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"越王問於大夫文種說道：吾欲伐吳可乎？對說道：可矣。吾賞賜恩惠厚而且信，刑罰制裁嚴而且必。君主統治者欲知的，何不試焚宮室？於是遂焚宮室，人莫救的，乃下令說道：人的救火的人或事物，死，比死敵的賞賜恩惠。救火而且不死的人或事物，比勝敵的賞賜恩惠。不救火的人或事物，比降北的罪。人塗他的體、被濡衣而且走火的人或事物，左三千人，右三千人。此知必勝的至高權力威勢啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 45 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「越王問於大夫文種曰：「吾欲伐吳可乎」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「越王問於大夫文種曰：「吾欲伐吳可乎？」對曰：「可矣。……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-46\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":46,\"canonicalText\":\"吳起為魏武侯西河之守，秦有小亭臨境，吳起欲攻之。不去，則甚害田者；去之，則不足以徵甲兵。於是乃倚一車轅於北門之外而令之曰：「有能徙此南門之外者賜之上田上宅。」人莫之徙也，及有徙之者，還，賜之如令。俄又置一石赤菽東門之外而令之曰：「有能徙此於西門之外者賜之如初。」人爭徙之。乃下令曰：「明日且攻亭，有能先登者，仕之國大夫，賜之上田宅。」人爭趨之，於是攻亭一朝而拔之。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-46_s-1\",\"han-fei-zi_ch-30_p-46_s-2\",\"han-fei-zi_ch-30_p-46_s-3\",\"han-fei-zi_ch-30_p-46_s-4\",\"han-fei-zi_ch-30_p-46_s-5\",\"han-fei-zi_ch-30_p-46_s-6\",\"han-fei-zi_ch-30_p-46_s-7\",\"han-fei-zi_ch-30_p-46_s-8\",\"han-fei-zi_ch-30_p-46_s-9\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"吳起為魏武侯西河的守，秦有小亭臨境，吳起欲攻的。不去，則甚害田的人或事物；去的，則不足以徵甲兵。於是乃倚一車轅於北門的外而且令的說道：有能徙此南門的外的人或事物賜的上田上宅。人莫的徙啊，及有徙的的人或事物，還，賜的如令。俄又置一石赤菽東門的外而且令的說道：有能徙此於西門的外的人或事物賜的如初。人爭徙的。乃下令說道：明日且攻亭，有能先登的人或事物，仕的國大夫，賜的上田宅。人爭趨的，於是攻亭一朝而且拔的。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 46 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「吳起為魏武侯西河之守，秦有小亭臨境，吳起欲攻之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「吳起為魏武侯西河之守，秦有小亭臨境，吳起欲攻之。不去……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-47\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":47,\"canonicalText\":\"李悝為魏文侯上地之守，而欲人之善射也，乃下令曰：「人之有狐疑之訟者，令之射的，中之者勝，不中者負。」令下而人皆疾習射，日夜不休。及與秦人戰，大敗之，以人之善射也。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-47_s-1\",\"han-fei-zi_ch-30_p-47_s-2\",\"han-fei-zi_ch-30_p-47_s-3\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"李悝為魏文侯上地的守，而且欲人的善射啊，乃下令說道：人的有狐疑的訟的人或事物，令的射的，中的的人或事物勝，不中的人或事物負。令下而且人皆疾習射，日夜不休。及與秦人戰，大敗的，以人的善射啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 47 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「李悝為魏文侯上地之守，而欲人之善射也，乃下令曰：「人之有狐疑之訟者，令之射的，中之者勝，不中者負」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「李悝為魏文侯上地之守，而欲人之善射也，乃下令曰：「人……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-48\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":48,\"canonicalText\":\"宋崇門之巷人服喪，而毀甚瘠，上以為慈愛於親，舉以為官師。明年，人之所以毀死者歲十餘人。子之服親喪者為愛之也，而尚可以賞勸也，況君上之於民乎？\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-48_s-1\",\"han-fei-zi_ch-30_p-48_s-2\",\"han-fei-zi_ch-30_p-48_s-3\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"宋崇門的巷人服喪，而且毀甚瘠，上以為慈愛於親，舉以為官師。明年，人的所以毀死的人或事物歲十餘人。子的服親喪的人或事物為愛的啊，而且尚可以賞賜恩惠勸啊，況君主統治者上的於民乎？\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 48 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「宋崇門之巷人服喪，而毀甚瘠，上以為慈愛於親，舉以為官師」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「宋崇門之巷人服喪，而毀甚瘠，上以為慈愛於親，舉以為官……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-49\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":49,\"canonicalText\":\"越王慮伐吳，欲人之輕死也，出見怒蛙乃為之式，從者曰：「奚敬於此？」王曰：「為其有氣故也。」明年之請以頭獻王者歲十餘人。由此觀之，譽之足以殺人矣。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-49_s-1\",\"han-fei-zi_ch-30_p-49_s-2\",\"han-fei-zi_ch-30_p-49_s-3\",\"han-fei-zi_ch-30_p-49_s-4\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"越王慮伐吳，欲人的輕死啊，出見怒蛙乃為的式，從的人或事物說道：奚敬於此？王說道：為他的有氣所以啊。明年的請以頭獻王的人或事物歲十餘人。由此觀的，譽的足以殺人矣。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 49 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「越王慮伐吳，欲人之輕死也，出見怒蛙乃為之式，從者曰：「奚敬於此」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「越王慮伐吳，欲人之輕死也，出見怒蛙乃為之式，從者曰：……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-50\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":50,\"canonicalText\":\"一曰。越王句踐見怒蛙而式之，御者曰：「何為式？」王曰：「蛙有氣如此，可無為式乎？」士人聞之曰：「蛙有氣，王猶為式，況士人之有勇者乎！」是歲人有自剄死以其頭獻者。故越王將復吳而試其教，燔臺而鼓之，使民赴火者，賞在火也，臨江而鼓之，使人赴水者，賞在水也，臨戰而使人絕頭刳腹而無顧心者，賞在兵也，又況據法而進賢，其助甚此矣。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-50_s-1\",\"han-fei-zi_ch-30_p-50_s-2\",\"han-fei-zi_ch-30_p-50_s-3\",\"han-fei-zi_ch-30_p-50_s-4\",\"han-fei-zi_ch-30_p-50_s-5\",\"han-fei-zi_ch-30_p-50_s-6\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"一說道：。越王句踐見怒蛙而且式的，御的人或事物說道：何為式？王說道：蛙有氣如此，可無為式乎？士人聞的說道：蛙有氣，王猶為式，況士人的有勇的人或事物乎！是歲人有自剄死以他的頭獻的人或事物。所以越王將復吳而且試他的教，燔臺而且鼓的，使民赴火的人或事物，賞賜恩惠在火啊，臨江而且鼓的，使人赴水的人或事物，賞賜恩惠在水啊，臨戰而且使人絕頭刳腹而且無顧心的人或事物，賞賜恩惠在兵啊，又況據國家法度法規而且進賢，他的助甚此矣。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 50 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。越王句踐見怒蛙而式之，御者曰：「何為式？」王曰……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-51\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":51,\"canonicalText\":\"韓昭侯使人藏弊褲，侍者曰：「君亦不仁矣，弊褲不以賜左右而藏之。」昭侯曰：「非子之所知也，吾聞明主之愛，一嚬一笑，嚬有為嚬，而笑有為笑。今夫褲豈特嚬笑哉！褲之與嚬笑相去遠矣，吾必待有功者，故藏之未有予也。」\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-51_s-1\",\"han-fei-zi_ch-30_p-51_s-2\",\"han-fei-zi_ch-30_p-51_s-3\",\"han-fei-zi_ch-30_p-51_s-4\",\"han-fei-zi_ch-30_p-51_s-5\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"韓昭侯使人藏弊褲，侍的人或事物說道：君主統治者亦不仁矣，弊褲不以賜左右而且藏的。昭侯說道：絕不是子的所知啊，吾聞明主的愛，一嚬一笑，嚬有為嚬，而且笑有為笑。如今社會上的褲豈特嚬笑哉！褲的與嚬笑相去遠矣，吾必待有功的人或事物，所以藏的未有予啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 51 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「韓昭侯使人藏弊褲，侍者曰：「君亦不仁矣，弊褲不以賜左右而藏之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「韓昭侯使人藏弊褲，侍者曰：「君亦不仁矣，弊褲不以賜左……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-52\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":52,\"canonicalText\":\"鱣似蛇，蠶似蠋。人見蛇則驚駭，見蠋則毛起。然而婦人拾蠶，漁者握鱣，利之所在，則忘其所惡，皆為孟賁。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-52_s-1\",\"han-fei-zi_ch-30_p-52_s-2\",\"han-fei-zi_ch-30_p-52_s-3\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"鱣似蛇，蠶似蠋。人見蛇則驚駭，見蠋則毛起。然而且婦人拾蠶，漁的人或事物握鱣，利的所在，則忘他的所惡，皆為孟賁。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 52 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「鱣似蛇，蠶似蠋」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「鱣似蛇，蠶似蠋。人見蛇則驚駭，見蠋則毛起。然而婦人拾……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-53\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":53,\"canonicalText\":\"說四\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-53_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說四。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 53 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「說四」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「說四」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-54\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":54,\"canonicalText\":\"魏王謂鄭王曰：「始鄭、梁一國也，已而別，今願復得鄭而合之梁。」鄭君患之，召群臣而與之謀所以對魏，鄭公子謂鄭君曰：「此甚易應也。君對魏曰：以鄭為故魏而可合也，則弊邑亦願得梁而合之鄭。」魏王乃止。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-54_s-1\",\"han-fei-zi_ch-30_p-54_s-2\",\"han-fei-zi_ch-30_p-54_s-3\",\"han-fei-zi_ch-30_p-54_s-4\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"魏王謂鄭王說道：始鄭、梁一國啊，已而且別，今願復得鄭而且合的梁。鄭君主統治者患的，召群臣下僚屬而且與的謀所以對魏，鄭公子謂鄭君主統治者說道：此甚易應啊。君主統治者對魏說道：以鄭為所以魏而且可合啊，則弊邑亦願得梁而且合的鄭。魏王乃止。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 54 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「魏王謂鄭王曰：「始鄭、梁一國也，已而別，今願復得鄭而合之梁」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「魏王謂鄭王曰：「始鄭、梁一國也，已而別，今願復得鄭而……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-55\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":55,\"canonicalText\":\"齊宣王使人吹竽，必三百人，南郭處士請為王吹竽，宣王說之，廩食以數百人。宣王死，湣王立，好一一聽之，處士逃。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-55_s-1\",\"han-fei-zi_ch-30_p-55_s-2\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"齊宣王使人吹竽，必三百人，南郭處士請為王吹竽，宣王說的，廩食以數百人。宣王死，湣王立，好一一聽的，處士逃。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 55 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「齊宣王使人吹竽，必三百人，南郭處士請為王吹竽，宣王說之，廩食以數百人」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「齊宣王使人吹竽，必三百人，南郭處士請為王吹竽，宣王說……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-56\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":56,\"canonicalText\":\"一曰。韓昭侯曰：「吹竽者眾，吾無以知其善者。」田嚴對曰：「一一而聽之。」\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-56_s-1\",\"han-fei-zi_ch-30_p-56_s-2\",\"han-fei-zi_ch-30_p-56_s-3\",\"han-fei-zi_ch-30_p-56_s-4\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"一說道：。韓昭侯說道：吹竽的人或事物眾，吾無以知他的善的人或事物。田嚴對說道：一一而且聽的。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 56 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。韓昭侯曰：「吹竽者眾，吾無以知其善者。」田嚴對……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-57\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":57,\"canonicalText\":\"趙令人因申子於韓請兵，將以攻魏，申子欲言之君，而恐君之疑己外市也，不則恐惡於趙，乃令趙紹、韓沓嘗試君之動貌而後言之，內則知昭侯之意，外則有得趙之功。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-57_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"趙令人因申子於韓請兵，將以攻魏，申子欲言的君主統治者，而且恐君主統治者的疑己外市啊，不則恐惡於趙，乃令趙紹、韓沓嘗試君主統治者的動貌而且後言的，內則知昭侯的意，外則有得趙的功。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 57 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「趙令人因申子於韓請兵，將以攻魏，申子欲言之君，而恐君之疑己外市也，不則恐惡於趙，乃令趙紹、韓沓嘗試君之動貌而後言之，內則知昭侯之意，外則有得趙之功」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「趙令人因申子於韓請兵，將以攻魏，申子欲言之君，而恐君……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-58\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":58,\"canonicalText\":\"三國兵至韓，秦王謂樓緩曰：「三國之兵深矣，寡人慾割河東而講，何如？」對曰：「夫割河東，大費也；免國於患，大功也。此父兄之任也，王何不召公子氾而問焉？」王召公子氾而告之，對曰：「講亦悔，不講亦悔。王今割河東而講，三國歸，王必曰：三國固且去矣，吾特以三城送之。不講，三國也入韓，則國必大舉矣，王必大悔，王曰：不獻三城也。臣故曰：王講亦悔，不講亦悔。」王曰：「為我悔也，寧亡三城而悔，無危乃悔。寡人斷講矣。」\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-58_s-1\",\"han-fei-zi_ch-30_p-58_s-2\",\"han-fei-zi_ch-30_p-58_s-3\",\"han-fei-zi_ch-30_p-58_s-4\",\"han-fei-zi_ch-30_p-58_s-5\",\"han-fei-zi_ch-30_p-58_s-6\",\"han-fei-zi_ch-30_p-58_s-7\",\"han-fei-zi_ch-30_p-58_s-8\",\"han-fei-zi_ch-30_p-58_s-9\",\"han-fei-zi_ch-30_p-58_s-10\",\"han-fei-zi_ch-30_p-58_s-11\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"三國兵至韓，秦王謂樓緩說道：三國的兵深矣，寡人慾割河東而且講，何如？對說道：夫割河東，大費啊；免國於患，大功啊。此父兄的任啊，王何不召公子氾而且問焉？王召公子氾而且告的，對說道：講亦悔，不講亦悔。王今割河東而且講，三國歸，王必說道：三國固且去矣，吾特以三城送的。不講，三國啊入韓，則國必大舉矣，王必大悔，王說道：不獻三城啊。臣下僚屬因此韓絕不是子評論說道：王講亦悔，不講亦悔。王說道：為我悔啊，寧亡三城而且悔，無危乃悔。寡人斷講矣。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 58 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「三國兵至韓，秦王謂樓緩曰：「三國之兵深矣，寡人慾割河東而講，何如」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「三國兵至韓，秦王謂樓緩曰：「三國之兵深矣，寡人慾割河……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-59\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":59,\"canonicalText\":\"應侯謂秦王曰：「王得宛葉、藍田、陽夏，斷河內，因梁、鄭，所以未王者，趙未服也。弛上黨在一而已以臨東陽，則邯鄲口中蝨也。王拱而朝天下，後者以兵中之。然上黨之安樂，其處甚劇，臣恐弛之而不聽，奈何？」王曰：「必弛易之矣。」\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-59_s-1\",\"han-fei-zi_ch-30_p-59_s-2\",\"han-fei-zi_ch-30_p-59_s-3\",\"han-fei-zi_ch-30_p-59_s-4\",\"han-fei-zi_ch-30_p-59_s-5\",\"han-fei-zi_ch-30_p-59_s-6\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"應侯謂秦王說道：王得宛葉、藍田、陽夏，斷河內，因梁、鄭，所以未王的人或事物，趙未服啊。弛上黨在一而且已以臨東陽，則邯鄲口中蝨啊。王拱而且朝天下，後的人或事物以兵中的。然上黨的安樂，他的處甚劇，臣下僚屬恐弛的而且不聽，奈何？王說道：必弛易的矣。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 59 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「應侯謂秦王曰：「王得宛葉、藍田、陽夏，斷河內，因梁、鄭，所以未王者，趙未服也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「應侯謂秦王曰：「王得宛葉、藍田、陽夏，斷河內，因梁、……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-60\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":60,\"canonicalText\":\"說五\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-60_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說五。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 60 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「說五」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「說五」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-61\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":61,\"canonicalText\":\"龐敬，縣令也，遣市者行，而召公大夫而還之，立有間，無以詔之，卒遣行，市者以為令與公大夫有言，不相信，以至無姦。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-61_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"龐敬，縣令啊，遣市的人或事物行，而且召公大夫而且還的，立有間，無以詔的，卒遣行，市的人或事物以為令與公大夫有言，不相信，以至無姦。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 61 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「龐敬，縣令也，遣市者行，而召公大夫而還之，立有間，無以詔之，卒遣行，市者以為令與公大夫有言，不相信，以至無姦」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「龐敬，縣令也，遣市者行，而召公大夫而還之，立有間，無……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-62\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":62,\"canonicalText\":\"戴驩、宋太宰，夜使人曰：「吾聞數夜有乘轀車至李史門者，謹為我伺之。」使人報曰：「不見轀車，見有奉笥而與李史語者，有間，李史受笥。」\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-62_s-1\",\"han-fei-zi_ch-30_p-62_s-2\",\"han-fei-zi_ch-30_p-62_s-3\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"戴驩、宋太宰，夜使人說道：吾聞數夜有乘轀車至李史門的人或事物，謹為我伺的。使人報說道：不見轀車，見有奉笥而且與李史語的人或事物，有間，李史受笥。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 62 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「戴驩、宋太宰，夜使人曰：「吾聞數夜有乘轀車至李史門者，謹為我伺之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「戴驩、宋太宰，夜使人曰：「吾聞數夜有乘轀車至李史門者……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-63\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":63,\"canonicalText\":\"周主亡玉簪，令吏求之，三日不能得也，周主令人求而得之家人之屋閒，周主曰：「吾知吏之不事事也。求簪，三日不得之，吾令人求之，不移日而得之。」於是吏皆聳懼，以為君、神明也。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-63_s-1\",\"han-fei-zi_ch-30_p-63_s-2\",\"han-fei-zi_ch-30_p-63_s-3\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"周主亡玉簪，令吏求的，三日不能得啊，周主令人求而且得的家人的屋閒，周主說道：吾知吏的不事事啊。求簪，三日不得的，吾令人求的，不移日而且得的。於是吏皆聳懼，以為君主統治者、神明啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 63 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「周主亡玉簪，令吏求之，三日不能得也，周主令人求而得之家人之屋閒，周主曰：「吾知吏之不事事也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「周主亡玉簪，令吏求之，三日不能得也，周主令人求而得之……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-64\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":64,\"canonicalText\":\"商太宰使少庶子之市，顧反而問之曰：「何見於市？」對曰：「無見也。」太宰曰：「雖然何見也？」對曰：「市南門之外甚眾牛車，僅可以行耳。」太宰因誡使者無敢告人吾所問於女，因召市吏而誚之曰：「市門之外何多牛屎？」市吏甚怪太宰知之疾也，乃悚懼其所也。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-64_s-1\",\"han-fei-zi_ch-30_p-64_s-2\",\"han-fei-zi_ch-30_p-64_s-3\",\"han-fei-zi_ch-30_p-64_s-4\",\"han-fei-zi_ch-30_p-64_s-5\",\"han-fei-zi_ch-30_p-64_s-6\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"商太宰使少庶子的市，顧反而且問的說道：何見於市？對說道：無見啊。太宰說道：雖然何見啊？對說道：市南門的外甚眾牛車，僅可以行耳。太宰因誡使的人或事物無敢告人吾所問於女，因召市吏而且誚的說道：市門的外何多牛屎？市吏甚怪太宰知的疾啊，乃悚懼他的所啊。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 64 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「商太宰使少庶子之市，顧反而問之曰：「何見於市」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「商太宰使少庶子之市，顧反而問之曰：「何見於市？」對曰……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-65\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":65,\"canonicalText\":\"說六\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-65_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說六。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 65 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「說六」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「說六」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-66\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":66,\"canonicalText\":\"韓昭侯握爪而佯亡一爪，求之甚急，左右因割其爪而效之，昭侯以此察左右之誠不。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-66_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"韓昭侯握爪而且佯亡一爪，求的甚急，左右因割他的爪而且效的，昭侯以此察左右的誠不。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 66 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「韓昭侯握爪而佯亡一爪，求之甚急，左右因割其爪而效之，昭侯以此察左右之誠不」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「韓昭侯握爪而佯亡一爪，求之甚急，左右因割其爪而效之，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-67\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":67,\"canonicalText\":\"韓昭侯使騎於縣，使者報，昭侯問曰：「何見也？」對曰：「無所見也。」昭侯曰：「雖然何見？」曰：「南門之外，有黃犢食苗道左者。」昭侯謂使者「毋敢洩吾所問於女」，乃下令曰：「當苗時，禁牛馬入人田中固有令，而吏不以為事，牛馬甚多入人田中，亟舉其數上之，不得，將重其罪。」於是三鄉舉而上之，昭侯曰：「未盡也。」復往審之，乃得南門之外黃犢，吏以昭侯為明察，皆悚懼其所而不敢為非。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-67_s-1\",\"han-fei-zi_ch-30_p-67_s-2\",\"han-fei-zi_ch-30_p-67_s-3\",\"han-fei-zi_ch-30_p-67_s-4\",\"han-fei-zi_ch-30_p-67_s-5\",\"han-fei-zi_ch-30_p-67_s-6\",\"han-fei-zi_ch-30_p-67_s-7\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"韓昭侯使騎於縣，使的人或事物報，昭侯問說道：何見啊？對說道：無所見啊。昭侯說道：雖然何見？說道：南門的外，有黃犢食苗道左的人或事物。昭侯謂使的人或事物毋敢洩吾所問於女，乃下令說道：當苗時，禁牛馬入人田中固有令，而且吏不以為事，牛馬甚多入人田中，亟舉他的數上的，不得，將重他的罪。於是三鄉舉而且上的，昭侯說道：未盡啊。復往審的，乃得南門的外黃犢，吏以昭侯為明察，皆悚懼他的所而且不敢為絕不是。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 67 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「韓昭侯使騎於縣，使者報，昭侯問曰：「何見也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「韓昭侯使騎於縣，使者報，昭侯問曰：「何見也？」對曰：……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-68\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":68,\"canonicalText\":\"周主下令索曲杖，吏求之數日不能得，周主私使人求之，不移日而得之，乃謂吏曰：「吾知吏不事事也。曲杖甚易也，而吏不能得，我令人求之，不移日而得之，豈可謂忠哉？」吏乃皆悚懼其所，以君為神明。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-68_s-1\",\"han-fei-zi_ch-30_p-68_s-2\",\"han-fei-zi_ch-30_p-68_s-3\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"周主下令索曲杖，吏求的數日不能得，周主私使人求的，不移日而且得的，乃謂吏說道：吾知吏不事事啊。曲杖甚易啊，而且吏不能得，我令人求的，不移日而且得的，豈可謂忠哉？吏乃皆悚懼他的所，以君主統治者為神明。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 68 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「周主下令索曲杖，吏求之數日不能得，周主私使人求之，不移日而得之，乃謂吏曰：「吾知吏不事事也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「周主下令索曲杖，吏求之數日不能得，周主私使人求之，不……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-69\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":69,\"canonicalText\":\"卜皮為縣令。其御史汙穢，而有愛妾，卜皮乃使少庶子佯愛之以知御史陰情。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-69_s-1\",\"han-fei-zi_ch-30_p-69_s-2\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"卜皮為縣令。他的御史汙穢，而且有愛妾，卜皮乃使少庶子佯愛的以知御史陰情。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 69 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「卜皮為縣令」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「卜皮為縣令。其御史汙穢，而有愛妾，卜皮乃使少庶子佯愛……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-70\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":70,\"canonicalText\":\"西門豹為鄴令，佯亡其車轄，令吏求之不能得，使人求之而得之家人屋間。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-70_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"西門豹為鄴令，佯亡他的車轄，令吏求的不能得，使人求的而且得的家人屋間。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 70 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「西門豹為鄴令，佯亡其車轄，令吏求之不能得，使人求之而得之家人屋間」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「西門豹為鄴令，佯亡其車轄，令吏求之不能得，使人求之而……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-71\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":71,\"canonicalText\":\"說七\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-71_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"說七。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 71 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「說七」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「說七」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-72\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":72,\"canonicalText\":\"陽山君相衛，聞王之疑己也，乃偽謗樛豎以知之。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-72_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"陽山君主統治者相衛，聞王的疑己啊，乃偽謗樛豎以知的。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 72 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「陽山君相衛，聞王之疑己也，乃偽謗樛豎以知之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「陽山君相衛，聞王之疑己也，乃偽謗樛豎以知之。」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-73\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":73,\"canonicalText\":\"淖齒聞齊王之惡己也，乃矯為秦使以知之。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-73_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"淖齒聞齊王的惡己啊，乃矯為秦使以知的。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 73 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「淖齒聞齊王之惡己也，乃矯為秦使以知之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「淖齒聞齊王之惡己也，乃矯為秦使以知之。」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-74\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":74,\"canonicalText\":\"齊人有欲為亂者，恐王知之，因詐逐所愛者，令走王知之。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-74_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"齊人有欲為亂的人或事物，恐王知的，因詐逐所愛的人或事物，令走王知的。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 74 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「齊人有欲為亂者，恐王知之，因詐逐所愛者，令走王知之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「齊人有欲為亂者，恐王知之，因詐逐所愛者，令走王知之。」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-75\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":75,\"canonicalText\":\"子之相燕，坐而佯言曰：「走出門者何白馬也？」左右皆言不見。有一人走追之，報曰：「有。」子之以此知左右之誠信不。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-75_s-1\",\"han-fei-zi_ch-30_p-75_s-2\",\"han-fei-zi_ch-30_p-75_s-3\",\"han-fei-zi_ch-30_p-75_s-4\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"子的相燕，坐而且佯言說道：走出門的人或事物何白馬啊？左右皆言不見。有一人走追的，報說道：有。子的以此知左右的誠信不。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 75 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「子之相燕，坐而佯言曰：「走出門者何白馬也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「子之相燕，坐而佯言曰：「走出門者何白馬也？」左右皆言……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-76\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":76,\"canonicalText\":\"有相與訟者，子產離之而無使得通辭，倒其言以告而知之。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-76_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"有相與訟的人或事物，子產離的而且無使得通辭，倒他的言以告而且知的。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 76 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「有相與訟者，子產離之而無使得通辭，倒其言以告而知之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「有相與訟者，子產離之而無使得通辭，倒其言以告而知之。」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-30_p-77\",\"chapterId\":\"han-fei-zi_ch-30\",\"order\":77,\"canonicalText\":\"衛嗣公使人為客過關市，關市苛難之，因事關市以金，關吏乃舍之，嗣公為關吏曰：「某時有客過而所，與汝金，而汝因遣之。」關市乃大恐，而以嗣公為明察。\",\"sentenceIds\":[\"han-fei-zi_ch-30_p-77_s-1\",\"han-fei-zi_ch-30_p-77_s-2\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"衛嗣公使人為客過關市，關市苛難的，因事關市以金，關吏乃舍的，嗣公為關吏說道：某時有客過而且所，與汝金，而且汝因遣的。關市乃大恐，而且以嗣公為明察。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈內儲說上〉（第 77 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「衛嗣公使人為客過關市，關市苛難之，因事關市以金，關吏乃舍之，嗣公為關吏曰：「某時有客過而所，與汝金，而汝因遣之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「衛嗣公使人為客過關市，關市苛難之，因事關市以金，關吏……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"han-fei-zi_ch-30_p-1_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-1\",\"order\":1,\"canonicalText\":\"主之所用也七術，所察也六微。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-1_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-1\",\"order\":2,\"canonicalText\":\"七術：一曰、眾端參觀，二曰、必罰明威，三曰、信賞盡能，四曰、一聽責下，五曰、疑詔詭使，六曰、挾知而問，七曰、倒言反事。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-1_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-1\",\"order\":3,\"canonicalText\":\"此七者，主之所用也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-2_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-2\",\"order\":1,\"canonicalText\":\"觀聽不參則誠不聞，聽有門戶則臣壅塞。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-2_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-2\",\"order\":2,\"canonicalText\":\"其說在侏儒之夢見竈，哀公之稱莫眾而迷。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-2_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-2\",\"order\":3,\"canonicalText\":\"故齊人見河伯，與惠子之言亡其半也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-2_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-2\",\"order\":4,\"canonicalText\":\"其患在豎牛之餓叔孫，而江乙之說荊俗也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-2_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-2\",\"order\":5,\"canonicalText\":\"嗣公欲治不知，故使有敵。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-2_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-2\",\"order\":6,\"canonicalText\":\"是以明主推積鐵之類，而察一市之患。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-3_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-3\",\"order\":1,\"canonicalText\":\"參觀一\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-4_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-4\",\"order\":1,\"canonicalText\":\"愛多者則法不立，威寡者則下侵上。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-4_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-4\",\"order\":2,\"canonicalText\":\"是以刑罰不必則禁令不行。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-4_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-4\",\"order\":3,\"canonicalText\":\"其說在董子之行石邑，與子產之教遊吉也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-4_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-4\",\"order\":4,\"canonicalText\":\"故仲尼說隕霜，而殷法刑棄灰；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-4_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-4\",\"order\":5,\"canonicalText\":\"將行去樂池，而公孫鞅重輕罪。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-4_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-4\",\"order\":6,\"canonicalText\":\"是以麗水之金不守，而積澤之火不救。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-4_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-4\",\"order\":7,\"canonicalText\":\"成歡以太仁弱齊國，卜皮以慈惠亡魏王。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-4_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-4\",\"order\":8,\"canonicalText\":\"管仲知之，故斷死人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-4_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-4\",\"order\":9,\"canonicalText\":\"嗣公知之，故買胥靡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-5_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-5\",\"order\":1,\"canonicalText\":\"必罰二\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-6_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-6\",\"order\":1,\"canonicalText\":\"賞譽薄而謾者，下不用也，賞譽厚而信者下輕死。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-6_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-6\",\"order\":2,\"canonicalText\":\"其說在文子稱若獸鹿。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-6_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-6\",\"order\":3,\"canonicalText\":\"故越王焚宮室，而吳起倚車轅，李悝斷訟以射，宋崇門以毀死。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-6_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-6\",\"order\":4,\"canonicalText\":\"句踐知之，故式怒蛙。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-6_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-6\",\"order\":5,\"canonicalText\":\"昭侯知之，故藏弊褲。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-6_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-6\",\"order\":6,\"canonicalText\":\"厚賞之使人為賁、諸也，婦人之拾蠶，漁者之握鱣，是以效之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-7_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-7\",\"order\":1,\"canonicalText\":\"賞譽三\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-8_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-8\",\"order\":1,\"canonicalText\":\"一聽則智愚不分，責下則人臣不參。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-8_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-8\",\"order\":2,\"canonicalText\":\"其說在索鄭與吹竽。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-8_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-8\",\"order\":3,\"canonicalText\":\"其患在申子之以趙紹、韓沓為嘗試。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-8_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-8\",\"order\":4,\"canonicalText\":\"故公子氾議割河東，而應侯謀弛上黨。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-9_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-9\",\"order\":1,\"canonicalText\":\"一聽四\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-10_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-10\",\"order\":1,\"canonicalText\":\"數見久待而不任，姦則鹿散。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-10_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-10\",\"order\":2,\"canonicalText\":\"使人問他則不鬻私。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-10_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-10\",\"order\":3,\"canonicalText\":\"是以龐敬還公大夫，而戴讙詔視轀車。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-10_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-10\",\"order\":4,\"canonicalText\":\"周主亡玉簪，商太宰論牛矢。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-11_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-11\",\"order\":1,\"canonicalText\":\"詭使五\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-12_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-12\",\"order\":1,\"canonicalText\":\"挾智而問，則不智者至；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-12_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-12\",\"order\":2,\"canonicalText\":\"深智一物，眾隱皆變。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-12_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-12\",\"order\":3,\"canonicalText\":\"其說在昭侯之握一爪也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-12_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-12\",\"order\":4,\"canonicalText\":\"故必南門而三鄉得。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-12_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-12\",\"order\":5,\"canonicalText\":\"周主索曲杖而群臣懼，卜皮事庶子，西門豹詳遺轄。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-13_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-13\",\"order\":1,\"canonicalText\":\"挾智六\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-14_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-14\",\"order\":1,\"canonicalText\":\"倒言反事以嘗所疑則姦情得。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-14_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-14\",\"order\":2,\"canonicalText\":\"故陽山謾樛豎，淖齒為秦使，齊人慾為亂，子之以白馬，子產離訟者，嗣公過關市。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-15_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-15\",\"order\":1,\"canonicalText\":\"倒言七\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-16_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-16\",\"order\":1,\"canonicalText\":\"右經\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-17_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-17\",\"order\":1,\"canonicalText\":\"說一\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-18_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-18\",\"order\":1,\"canonicalText\":\"衛靈公之時，彌子瑕有寵，專於衛國，侏儒有見公者曰：「臣之夢踐矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-18_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-18\",\"order\":2,\"canonicalText\":\"」公曰：「何夢？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-18_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-18\",\"order\":3,\"canonicalText\":\"」對曰：「夢見竈，為見公也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-18_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-18\",\"order\":4,\"canonicalText\":\"」公怒曰：「吾聞見人主者夢見日，奚為見寡人而夢見竈？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-18_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-18\",\"order\":5,\"canonicalText\":\"」對曰：「夫日兼燭天下，一物不能當也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-18_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-18\",\"order\":6,\"canonicalText\":\"人君兼燭一國，一人不能壅也，故將見人主者夢見日。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-18_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-18\",\"order\":7,\"canonicalText\":\"夫竈一人煬焉，則後人無從見矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-18_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-18\",\"order\":8,\"canonicalText\":\"今或者一人、有煬君者乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-18_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-18\",\"order\":9,\"canonicalText\":\"則臣雖夢見竈，不亦可乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-18_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-18\",\"order\":10,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-19_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-19\",\"order\":1,\"canonicalText\":\"魯哀公問於孔子曰：「鄙諺曰：莫眾而迷。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-19_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-19\",\"order\":2,\"canonicalText\":\"今寡人舉事，與群臣慮之，而國愈亂，其故何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-19_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-19\",\"order\":3,\"canonicalText\":\"」孔子對曰：「明主之問臣，一人知之，一人不知也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-19_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-19\",\"order\":4,\"canonicalText\":\"如是者，明主在上，群臣直議於下。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-19_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-19\",\"order\":5,\"canonicalText\":\"今群臣無不一辭同軌乎季孫者，舉魯國盡化為一，君雖問境內之人，猶不免於亂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-19_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-19\",\"order\":6,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-20_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-20\",\"order\":1,\"canonicalText\":\"一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-20_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-20\",\"order\":2,\"canonicalText\":\"晏子聘魯，哀公問曰：「語曰：莫三人而迷。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-20_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-20\",\"order\":3,\"canonicalText\":\"今寡人與一國慮之，魯不免於亂何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-20_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-20\",\"order\":4,\"canonicalText\":\"」晏子曰：「古之所謂莫三人而迷者，一人失之，二人得之，三人足以為眾矣，故曰莫三人而迷。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-20_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-20\",\"order\":5,\"canonicalText\":\"今魯國之群臣以千百數，一言於季氏之私，人數非不眾，所言者一人也，安得三哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-20_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-20\",\"order\":6,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-21_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-21\",\"order\":1,\"canonicalText\":\"齊人有謂齊王曰：「河伯，大神也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-21_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-21\",\"order\":2,\"canonicalText\":\"王何不試與之遇乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-21_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-21\",\"order\":3,\"canonicalText\":\"臣請使王遇之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-21_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-21\",\"order\":4,\"canonicalText\":\"」乃為壇場大水之上，而與王立之焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-21_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-21\",\"order\":5,\"canonicalText\":\"有閒，大魚動，因曰：「此河伯。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-21_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-21\",\"order\":6,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-22_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-22\",\"order\":1,\"canonicalText\":\"張儀欲以秦、韓與魏之勢伐齊、荊，而惠施欲以齊、荊偃兵。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-22_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-22\",\"order\":2,\"canonicalText\":\"二人爭之，群臣左右皆為張子言，而以攻齊、荊為利，而莫為惠子言，王果聽張子，而以惠子言為不可。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-22_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-22\",\"order\":3,\"canonicalText\":\"攻齊、荊事已定，惠子入見，王言曰：「先生毋言矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-22_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-22\",\"order\":4,\"canonicalText\":\"攻齊、荊之事果利矣，一國盡以為然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-22_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-22\",\"order\":5,\"canonicalText\":\"」惠子因說：「不可不察也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-22_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-22\",\"order\":6,\"canonicalText\":\"夫齊、荊之事也誠利，一國盡以為利，是何智者之眾也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-22_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-22\",\"order\":7,\"canonicalText\":\"攻齊、荊之事誠不利，一國盡以為利，何愚者之眾也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-22_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-22\",\"order\":8,\"canonicalText\":\"凡謀者，疑也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-22_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-22\",\"order\":9,\"canonicalText\":\"疑也者，誠疑，以為可者半，以為不可者半。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-22_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-22\",\"order\":10,\"canonicalText\":\"今一國盡以為可，是王亡半也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-22_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-22\",\"order\":11,\"canonicalText\":\"劫主者固亡其半者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-22_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-22\",\"order\":12,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-23_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-23\",\"order\":1,\"canonicalText\":\"叔孫相魯，貴而主斷。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-23_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-23\",\"order\":2,\"canonicalText\":\"其所愛者曰豎牛，亦擅用叔孫之令。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-23_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-23\",\"order\":3,\"canonicalText\":\"叔孫有子曰壬，豎牛妒而欲殺之，因與壬遊於魯君所，魯君賜之玉環，壬拜受之而不敢佩，使豎牛請之叔孫，豎牛欺之曰：「吾已為爾請之矣，使爾佩之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-23_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-23\",\"order\":4,\"canonicalText\":\"」壬因佩之，豎牛因謂叔孫：「何不見壬於君乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-23_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-23\",\"order\":5,\"canonicalText\":\"」叔孫曰：「孺子何足見也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-23_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-23\",\"order\":6,\"canonicalText\":\"」豎牛曰：「壬固已數見於君矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-23_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-23\",\"order\":7,\"canonicalText\":\"君賜之玉環，壬已佩之矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-23_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-23\",\"order\":8,\"canonicalText\":\"」叔孫召壬見之，而果佩之，叔孫怒而殺壬。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-23_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-23\",\"order\":9,\"canonicalText\":\"壬兄曰丙，豎牛又妒而欲殺之，叔孫為丙鑄鐘，鐘成，丙不敢擊，使豎牛請之叔孫，豎牛不為請，又欺之曰：「吾已為爾請之矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-23_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-23\",\"order\":10,\"canonicalText\":\"使爾擊之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-23_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-23\",\"order\":11,\"canonicalText\":\"」丙因擊之，叔孫聞之曰：「丙不請而擅擊鐘。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-23_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-23\",\"order\":12,\"canonicalText\":\"」怒而逐之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-23_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-23\",\"order\":13,\"canonicalText\":\"丙出走齊，居一年，豎牛為謝叔孫，叔孫使豎牛召之，又不召而報之曰：「吾已召之矣，丙怒甚，不肯來。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-23_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-23\",\"order\":14,\"canonicalText\":\"」叔孫大怒，使人殺之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-23_s-15\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-23\",\"order\":15,\"canonicalText\":\"二子已死，叔孫有病，豎牛因獨養之而去左右，不內人，曰：「叔孫不欲聞人聲。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-23_s-16\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-23\",\"order\":16,\"canonicalText\":\"」因不食而餓殺。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-23_s-17\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-23\",\"order\":17,\"canonicalText\":\"叔孫已死，豎牛因不發喪也，徙其府庫重寶空之而奔齊。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-23_s-18\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-23\",\"order\":18,\"canonicalText\":\"夫聽所信之言，而子父為人僇，此不參之患也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-24_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-24\",\"order\":1,\"canonicalText\":\"江乙為魏王使荊，謂荊王曰：「臣入王之境內，聞王之國俗曰：君子不蔽人之美，不言人之惡，誠有之乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-24_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-24\",\"order\":2,\"canonicalText\":\"」王曰：「有之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-24_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-24\",\"order\":3,\"canonicalText\":\"」「然則若白公之亂，得庶無危乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-24_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-24\",\"order\":4,\"canonicalText\":\"誠得如此，臣免死罪矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-24_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-24\",\"order\":5,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-25_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-25\",\"order\":1,\"canonicalText\":\"衛嗣君重如耳，愛世姬，而恐其皆因其愛重以壅己也，乃貴薄疑以敵如耳，尊魏姬以耦世姬，曰：「以是相參也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-25_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-25\",\"order\":2,\"canonicalText\":\"」嗣君知欲無壅，而未得其術也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-25_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-25\",\"order\":3,\"canonicalText\":\"夫不使賤議貴，下必坐上，而必待勢重之鈞也，而後敢相議，則是益樹壅塞之臣也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-25_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-25\",\"order\":4,\"canonicalText\":\"嗣君之壅乃始。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-26_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-26\",\"order\":1,\"canonicalText\":\"夫矢來有鄉，則積鐵以備一鄉；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-26_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-26\",\"order\":2,\"canonicalText\":\"矢來無鄉，則為鐵室以盡備之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-26_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-26\",\"order\":3,\"canonicalText\":\"備之則體不傷。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-26_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-26\",\"order\":4,\"canonicalText\":\"故彼以盡備之不傷，此以盡敵之無姦也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-27_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-27\",\"order\":1,\"canonicalText\":\"龐恭與太子質於邯鄲，謂魏王曰：「今一人言市有虎，王信之乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-27_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-27\",\"order\":2,\"canonicalText\":\"」曰：「不信。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-27_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-27\",\"order\":3,\"canonicalText\":\"」「二人言市有虎，王信之乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-27_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-27\",\"order\":4,\"canonicalText\":\"」曰：「不信。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-27_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-27\",\"order\":5,\"canonicalText\":\"」「三人言市有虎，王信之乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-27_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-27\",\"order\":6,\"canonicalText\":\"」王曰：「寡人信之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-27_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-27\",\"order\":7,\"canonicalText\":\"」龐恭曰：「夫市之無虎也明矣，然而三人言而成虎。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-27_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-27\",\"order\":8,\"canonicalText\":\"今邯鄲之去魏也遠於市，議臣者過於三人，願王察之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-27_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-27\",\"order\":9,\"canonicalText\":\"」龐恭從邯鄲反，竟不得見。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-28_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-28\",\"order\":1,\"canonicalText\":\"說二\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-29_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-29\",\"order\":1,\"canonicalText\":\"董閼於為趙上地守，行石邑山中，澗深，峭如牆，深百仞，因問其旁鄉左右曰：「人嘗有入此者乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-29_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-29\",\"order\":2,\"canonicalText\":\"」對曰：「無有。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-29_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-29\",\"order\":3,\"canonicalText\":\"」曰：「嬰兒癡聾狂悖之人嘗有入此者乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-29_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-29\",\"order\":4,\"canonicalText\":\"」對曰：「無有。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-29_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-29\",\"order\":5,\"canonicalText\":\"」「牛馬犬彘嘗有入此者乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-29_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-29\",\"order\":6,\"canonicalText\":\"」對曰：「無有。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-29_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-29\",\"order\":7,\"canonicalText\":\"」董閼於喟然太息曰：「吾能治矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-29_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-29\",\"order\":8,\"canonicalText\":\"使吾法之無赦，猶入澗之必死也，則人莫之敢犯也，何為不治？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-29_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-29\",\"order\":9,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-30_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-30\",\"order\":1,\"canonicalText\":\"子產相鄭，病將死，謂遊吉曰：「我死後，子必用鄭，必以嚴蒞人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-30_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-30\",\"order\":2,\"canonicalText\":\"夫火形嚴，故人鮮灼；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-30_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-30\",\"order\":3,\"canonicalText\":\"水形懦，人多溺。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-30_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-30\",\"order\":4,\"canonicalText\":\"子必嚴子之形，無令溺子之懦。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-30_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-30\",\"order\":5,\"canonicalText\":\"」故子產死，遊吉不肯嚴形，鄭少年相率為盜，處於雚澤，將遂以為鄭禍。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-30_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-30\",\"order\":6,\"canonicalText\":\"遊吉率車騎與戰，一日一夜，僅能剋之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-30_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-30\",\"order\":7,\"canonicalText\":\"遊吉喟然歎曰：「吾蚤行夫子之教，必不悔至於此矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-30_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-30\",\"order\":8,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-31_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-31\",\"order\":1,\"canonicalText\":\"魯哀公問於仲尼曰：「春秋之記曰：冬十二月霣霜不殺菽，何為記此？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-31_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-31\",\"order\":2,\"canonicalText\":\"」仲尼對曰：「此言可以殺而不殺也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-31_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-31\",\"order\":3,\"canonicalText\":\"夫宜殺而不殺，桃李冬實。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-31_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-31\",\"order\":4,\"canonicalText\":\"天失道，草木猶犯幹之，而況於人君乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-31_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-31\",\"order\":5,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-32_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-32\",\"order\":1,\"canonicalText\":\"殷之法刑棄灰於街者，子貢以為重，問之仲尼，仲尼曰：「知治之道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-32_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-32\",\"order\":2,\"canonicalText\":\"夫棄灰於街必掩人，掩人人必怒，怒則鬥，鬥必三族相殘也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-32_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-32\",\"order\":3,\"canonicalText\":\"此殘三族之道也，雖刑之可也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-32_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-32\",\"order\":4,\"canonicalText\":\"且夫重罰者，人之所惡也，而無棄灰，人之所易也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-32_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-32\",\"order\":5,\"canonicalText\":\"使人行之所易，而無離所惡，此治之道。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-32_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-32\",\"order\":6,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-33_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-33\",\"order\":1,\"canonicalText\":\"一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-33_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-33\",\"order\":2,\"canonicalText\":\"殷之法，棄灰於公道者斷其手，子貢曰：「棄灰之罪輕，斷手之罰重，古人何太毅也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-33_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-33\",\"order\":3,\"canonicalText\":\"」曰：「無棄灰所易也，斷手所惡也，行所易不關所惡，古人以為易，故行之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-33_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-33\",\"order\":4,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-34_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-34\",\"order\":1,\"canonicalText\":\"中山之相樂池以車百乘使趙，選其客之有智能者以為將行，中道而亂，樂池曰：「吾以公為有智，而使公為將行，今中道而亂何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-34_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-34\",\"order\":2,\"canonicalText\":\"」客因辭而去曰：「公不知治，有威足以服人，而利足以勸之，故能治之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-34_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-34\",\"order\":3,\"canonicalText\":\"今臣，君之少客也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-34_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-34\",\"order\":4,\"canonicalText\":\"夫從少正長，從賤治貴，而不得操其利害之柄以制之，此所以亂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-34_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-34\",\"order\":5,\"canonicalText\":\"嘗試使臣彼之善者我能以為卿相，彼不善者我得以斬其首，何故而不治？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-34_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-34\",\"order\":6,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-35_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-35\",\"order\":1,\"canonicalText\":\"公孫鞅之法也重輕罪。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-35_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-35\",\"order\":2,\"canonicalText\":\"重罪者人之所難犯也，而小過者人之所易去也，使人去其所易無離其所難，此治之道。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-35_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-35\",\"order\":3,\"canonicalText\":\"夫小過不生，大罪不至，是人無罪而亂不生也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-36_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-36\",\"order\":1,\"canonicalText\":\"一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-36_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-36\",\"order\":2,\"canonicalText\":\"公孫鞅曰：「行刑重其輕者，輕者不至，重者不來，是謂以刑去刑。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-36_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-36\",\"order\":3,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-37_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-37\",\"order\":1,\"canonicalText\":\"荊南之地、麗水之中生金，人多竊採金，採金之禁，得而輒辜磔於市，甚眾，壅離其水也，而人竊金不止。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-37_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-37\",\"order\":2,\"canonicalText\":\"夫罪莫重辜磔於市，猶不止者，不必得也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-37_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-37\",\"order\":3,\"canonicalText\":\"故今有於此，曰：「予汝天下而殺汝身」，庸人不為也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-37_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-37\",\"order\":4,\"canonicalText\":\"夫有天下，大利也，猶不為者，知必死。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-37_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-37\",\"order\":5,\"canonicalText\":\"故不必得也，則雖辜磔，竊金不止；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-37_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-37\",\"order\":6,\"canonicalText\":\"知必死，則天下不為也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-38_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-38\",\"order\":1,\"canonicalText\":\"魯人燒積澤，天北風，火南倚，恐燒國，哀公懼，自將眾趣救火，左右無人，盡逐獸而火不救，乃召問仲尼，仲尼曰：「夫逐獸者樂而無罰，救火者苦而無賞，此火之所以無救也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-38_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-38\",\"order\":2,\"canonicalText\":\"」哀公曰：「善。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-38_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-38\",\"order\":3,\"canonicalText\":\"」仲尼曰：「事急，不及以賞，救火者盡賞之，則國不足以賞於人，請徒行罰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-38_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-38\",\"order\":4,\"canonicalText\":\"」哀公曰：「善。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-38_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-38\",\"order\":5,\"canonicalText\":\"」於是仲尼乃下令曰：「不救火者比降北之罪，逐獸者比入禁之罪。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-38_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-38\",\"order\":6,\"canonicalText\":\"」令下未遍而火已救矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-39_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-39\",\"order\":1,\"canonicalText\":\"成驩謂齊王曰：「王太仁，太不忍人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-39_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-39\",\"order\":2,\"canonicalText\":\"」王曰：「太仁、太不忍人，非善名邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-39_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-39\",\"order\":3,\"canonicalText\":\"」對曰：「此人臣之善也，非人主之所行也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-39_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-39\",\"order\":4,\"canonicalText\":\"夫人臣必仁而後可與謀，不忍人而後可近也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-39_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-39\",\"order\":5,\"canonicalText\":\"不仁則不可與謀，忍人則不可近也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-39_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-39\",\"order\":6,\"canonicalText\":\"」王曰：「然則寡人安所太仁、安不忍人？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-39_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-39\",\"order\":7,\"canonicalText\":\"」對曰：「王太仁於薛公，而太不忍於諸田。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-39_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-39\",\"order\":8,\"canonicalText\":\"太仁薛公則大臣無重，太不忍諸田則父兄犯法。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-39_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-39\",\"order\":9,\"canonicalText\":\"大臣無重則兵弱於外，父兄犯法則政亂於內。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-39_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-39\",\"order\":10,\"canonicalText\":\"兵弱於外、政亂於內，此亡國之本也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-39_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-39\",\"order\":11,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-40_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-40\",\"order\":1,\"canonicalText\":\"魏惠王謂卜皮曰：「子聞寡人之聲聞亦何如焉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-40_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-40\",\"order\":2,\"canonicalText\":\"」對曰：「臣聞王之慈惠也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-40_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-40\",\"order\":3,\"canonicalText\":\"」王欣然喜曰：「然則功且安至？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-40_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-40\",\"order\":4,\"canonicalText\":\"」對曰：「王之功至於亡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-40_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-40\",\"order\":5,\"canonicalText\":\"」王曰：「慈惠，行善也，行之而亡何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-40_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-40\",\"order\":6,\"canonicalText\":\"」卜皮對曰：「夫慈者不忍，而惠者好與也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-40_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-40\",\"order\":7,\"canonicalText\":\"不忍則不誅有過，好予則不待有功而賞。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-40_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-40\",\"order\":8,\"canonicalText\":\"有過不罪，無功受賞，雖亡不亦可乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-40_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-40\",\"order\":9,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-41_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-41\",\"order\":1,\"canonicalText\":\"齊國好厚葬，布帛盡於衣衾，材木盡於棺槨，桓公患之，以告管仲曰：「布帛盡則無以為蔽，材木盡則無以為守備，而人厚葬之不休，禁之奈何？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-41_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-41\",\"order\":2,\"canonicalText\":\"」管仲對曰：「凡人之有為也，非名之則利之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-41_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-41\",\"order\":3,\"canonicalText\":\"」於是乃下令曰：「棺槨過度者戮其屍，罪夫當喪者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-41_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-41\",\"order\":4,\"canonicalText\":\"」夫戮死無名，罪當喪者無利，人何故為之也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-42_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-42\",\"order\":1,\"canonicalText\":\"衛嗣君之時，有胥靡逃之魏，因為襄王之後治病，衛嗣君聞之，使人請以五十金買之，五反而魏王不予，乃以左氏易之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-42_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-42\",\"order\":2,\"canonicalText\":\"群臣左右諫曰：「夫以一都買胥靡可乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-42_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-42\",\"order\":3,\"canonicalText\":\"」王曰：「非子之所知也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-42_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-42\",\"order\":4,\"canonicalText\":\"夫治無小而亂無大，法不立而誅不必，雖有十左氏無益也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-42_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-42\",\"order\":5,\"canonicalText\":\"法立而誅必，雖失十左氏無害也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-42_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-42\",\"order\":6,\"canonicalText\":\"」魏王聞之曰：「主欲治而不聽之，不祥。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-42_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-42\",\"order\":7,\"canonicalText\":\"」因載而往，徒獻之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-43_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-43\",\"order\":1,\"canonicalText\":\"說三\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-44_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-44\",\"order\":1,\"canonicalText\":\"齊王問於文子曰：「治國何如？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-44_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-44\",\"order\":2,\"canonicalText\":\"」對曰：「夫賞罰之為道，利器也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-44_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-44\",\"order\":3,\"canonicalText\":\"君固握之，不可以示人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-44_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-44\",\"order\":4,\"canonicalText\":\"若如臣者，猶獸鹿也，唯薦草而就。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-44_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-44\",\"order\":5,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-45_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-45\",\"order\":1,\"canonicalText\":\"越王問於大夫文種曰：「吾欲伐吳可乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-45_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-45\",\"order\":2,\"canonicalText\":\"」對曰：「可矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-45_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-45\",\"order\":3,\"canonicalText\":\"吾賞厚而信，罰嚴而必。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-45_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-45\",\"order\":4,\"canonicalText\":\"君欲知之，何不試焚宮室？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-45_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-45\",\"order\":5,\"canonicalText\":\"」於是遂焚宮室，人莫救之，乃下令曰：「人之救火者，死，比死敵之賞。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-45_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-45\",\"order\":6,\"canonicalText\":\"救火而不死者，比勝敵之賞。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-45_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-45\",\"order\":7,\"canonicalText\":\"不救火者，比降北之罪。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-45_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-45\",\"order\":8,\"canonicalText\":\"」人塗其體、被濡衣而走火者，左三千人，右三千人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-45_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-45\",\"order\":9,\"canonicalText\":\"此知必勝之勢也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-46_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-46\",\"order\":1,\"canonicalText\":\"吳起為魏武侯西河之守，秦有小亭臨境，吳起欲攻之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-46_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-46\",\"order\":2,\"canonicalText\":\"不去，則甚害田者；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-46_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-46\",\"order\":3,\"canonicalText\":\"去之，則不足以徵甲兵。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-46_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-46\",\"order\":4,\"canonicalText\":\"於是乃倚一車轅於北門之外而令之曰：「有能徙此南門之外者賜之上田上宅。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-46_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-46\",\"order\":5,\"canonicalText\":\"」人莫之徙也，及有徙之者，還，賜之如令。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-46_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-46\",\"order\":6,\"canonicalText\":\"俄又置一石赤菽東門之外而令之曰：「有能徙此於西門之外者賜之如初。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-46_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-46\",\"order\":7,\"canonicalText\":\"」人爭徙之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-46_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-46\",\"order\":8,\"canonicalText\":\"乃下令曰：「明日且攻亭，有能先登者，仕之國大夫，賜之上田宅。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-46_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-46\",\"order\":9,\"canonicalText\":\"」人爭趨之，於是攻亭一朝而拔之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-47_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-47\",\"order\":1,\"canonicalText\":\"李悝為魏文侯上地之守，而欲人之善射也，乃下令曰：「人之有狐疑之訟者，令之射的，中之者勝，不中者負。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-47_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-47\",\"order\":2,\"canonicalText\":\"」令下而人皆疾習射，日夜不休。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-47_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-47\",\"order\":3,\"canonicalText\":\"及與秦人戰，大敗之，以人之善射也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-48_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-48\",\"order\":1,\"canonicalText\":\"宋崇門之巷人服喪，而毀甚瘠，上以為慈愛於親，舉以為官師。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-48_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-48\",\"order\":2,\"canonicalText\":\"明年，人之所以毀死者歲十餘人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-48_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-48\",\"order\":3,\"canonicalText\":\"子之服親喪者為愛之也，而尚可以賞勸也，況君上之於民乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-49_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-49\",\"order\":1,\"canonicalText\":\"越王慮伐吳，欲人之輕死也，出見怒蛙乃為之式，從者曰：「奚敬於此？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-49_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-49\",\"order\":2,\"canonicalText\":\"」王曰：「為其有氣故也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-49_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-49\",\"order\":3,\"canonicalText\":\"」明年之請以頭獻王者歲十餘人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-49_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-49\",\"order\":4,\"canonicalText\":\"由此觀之，譽之足以殺人矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-50_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-50\",\"order\":1,\"canonicalText\":\"一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-50_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-50\",\"order\":2,\"canonicalText\":\"越王句踐見怒蛙而式之，御者曰：「何為式？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-50_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-50\",\"order\":3,\"canonicalText\":\"」王曰：「蛙有氣如此，可無為式乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-50_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-50\",\"order\":4,\"canonicalText\":\"」士人聞之曰：「蛙有氣，王猶為式，況士人之有勇者乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-50_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-50\",\"order\":5,\"canonicalText\":\"」是歲人有自剄死以其頭獻者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-50_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-50\",\"order\":6,\"canonicalText\":\"故越王將復吳而試其教，燔臺而鼓之，使民赴火者，賞在火也，臨江而鼓之，使人赴水者，賞在水也，臨戰而使人絕頭刳腹而無顧心者，賞在兵也，又況據法而進賢，其助甚此矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-51_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-51\",\"order\":1,\"canonicalText\":\"韓昭侯使人藏弊褲，侍者曰：「君亦不仁矣，弊褲不以賜左右而藏之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-51_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-51\",\"order\":2,\"canonicalText\":\"」昭侯曰：「非子之所知也，吾聞明主之愛，一嚬一笑，嚬有為嚬，而笑有為笑。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-51_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-51\",\"order\":3,\"canonicalText\":\"今夫褲豈特嚬笑哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-51_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-51\",\"order\":4,\"canonicalText\":\"褲之與嚬笑相去遠矣，吾必待有功者，故藏之未有予也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-51_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-51\",\"order\":5,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-52_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-52\",\"order\":1,\"canonicalText\":\"鱣似蛇，蠶似蠋。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-52_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-52\",\"order\":2,\"canonicalText\":\"人見蛇則驚駭，見蠋則毛起。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-52_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-52\",\"order\":3,\"canonicalText\":\"然而婦人拾蠶，漁者握鱣，利之所在，則忘其所惡，皆為孟賁。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-53_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-53\",\"order\":1,\"canonicalText\":\"說四\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-54_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-54\",\"order\":1,\"canonicalText\":\"魏王謂鄭王曰：「始鄭、梁一國也，已而別，今願復得鄭而合之梁。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-54_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-54\",\"order\":2,\"canonicalText\":\"」鄭君患之，召群臣而與之謀所以對魏，鄭公子謂鄭君曰：「此甚易應也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-54_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-54\",\"order\":3,\"canonicalText\":\"君對魏曰：以鄭為故魏而可合也，則弊邑亦願得梁而合之鄭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-54_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-54\",\"order\":4,\"canonicalText\":\"」魏王乃止。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-55_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-55\",\"order\":1,\"canonicalText\":\"齊宣王使人吹竽，必三百人，南郭處士請為王吹竽，宣王說之，廩食以數百人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-55_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-55\",\"order\":2,\"canonicalText\":\"宣王死，湣王立，好一一聽之，處士逃。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-56_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-56\",\"order\":1,\"canonicalText\":\"一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-56_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-56\",\"order\":2,\"canonicalText\":\"韓昭侯曰：「吹竽者眾，吾無以知其善者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-56_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-56\",\"order\":3,\"canonicalText\":\"」田嚴對曰：「一一而聽之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-56_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-56\",\"order\":4,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-57_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-57\",\"order\":1,\"canonicalText\":\"趙令人因申子於韓請兵，將以攻魏，申子欲言之君，而恐君之疑己外市也，不則恐惡於趙，乃令趙紹、韓沓嘗試君之動貌而後言之，內則知昭侯之意，外則有得趙之功。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-58_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-58\",\"order\":1,\"canonicalText\":\"三國兵至韓，秦王謂樓緩曰：「三國之兵深矣，寡人慾割河東而講，何如？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-58_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-58\",\"order\":2,\"canonicalText\":\"」對曰：「夫割河東，大費也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-58_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-58\",\"order\":3,\"canonicalText\":\"免國於患，大功也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-58_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-58\",\"order\":4,\"canonicalText\":\"此父兄之任也，王何不召公子氾而問焉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-58_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-58\",\"order\":5,\"canonicalText\":\"」王召公子氾而告之，對曰：「講亦悔，不講亦悔。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-58_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-58\",\"order\":6,\"canonicalText\":\"王今割河東而講，三國歸，王必曰：三國固且去矣，吾特以三城送之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-58_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-58\",\"order\":7,\"canonicalText\":\"不講，三國也入韓，則國必大舉矣，王必大悔，王曰：不獻三城也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-58_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-58\",\"order\":8,\"canonicalText\":\"臣故曰：王講亦悔，不講亦悔。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-58_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-58\",\"order\":9,\"canonicalText\":\"」王曰：「為我悔也，寧亡三城而悔，無危乃悔。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-58_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-58\",\"order\":10,\"canonicalText\":\"寡人斷講矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-58_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-58\",\"order\":11,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-59_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-59\",\"order\":1,\"canonicalText\":\"應侯謂秦王曰：「王得宛葉、藍田、陽夏，斷河內，因梁、鄭，所以未王者，趙未服也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-59_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-59\",\"order\":2,\"canonicalText\":\"弛上黨在一而已以臨東陽，則邯鄲口中蝨也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-59_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-59\",\"order\":3,\"canonicalText\":\"王拱而朝天下，後者以兵中之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-59_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-59\",\"order\":4,\"canonicalText\":\"然上黨之安樂，其處甚劇，臣恐弛之而不聽，奈何？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-59_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-59\",\"order\":5,\"canonicalText\":\"」王曰：「必弛易之矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-59_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-59\",\"order\":6,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-60_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-60\",\"order\":1,\"canonicalText\":\"說五\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-61_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-61\",\"order\":1,\"canonicalText\":\"龐敬，縣令也，遣市者行，而召公大夫而還之，立有間，無以詔之，卒遣行，市者以為令與公大夫有言，不相信，以至無姦。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-62_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-62\",\"order\":1,\"canonicalText\":\"戴驩、宋太宰，夜使人曰：「吾聞數夜有乘轀車至李史門者，謹為我伺之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-62_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-62\",\"order\":2,\"canonicalText\":\"」使人報曰：「不見轀車，見有奉笥而與李史語者，有間，李史受笥。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-62_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-62\",\"order\":3,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-63_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-63\",\"order\":1,\"canonicalText\":\"周主亡玉簪，令吏求之，三日不能得也，周主令人求而得之家人之屋閒，周主曰：「吾知吏之不事事也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-63_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-63\",\"order\":2,\"canonicalText\":\"求簪，三日不得之，吾令人求之，不移日而得之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-63_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-63\",\"order\":3,\"canonicalText\":\"」於是吏皆聳懼，以為君、神明也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-64_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-64\",\"order\":1,\"canonicalText\":\"商太宰使少庶子之市，顧反而問之曰：「何見於市？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-64_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-64\",\"order\":2,\"canonicalText\":\"」對曰：「無見也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-64_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-64\",\"order\":3,\"canonicalText\":\"」太宰曰：「雖然何見也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-64_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-64\",\"order\":4,\"canonicalText\":\"」對曰：「市南門之外甚眾牛車，僅可以行耳。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-64_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-64\",\"order\":5,\"canonicalText\":\"」太宰因誡使者無敢告人吾所問於女，因召市吏而誚之曰：「市門之外何多牛屎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-64_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-64\",\"order\":6,\"canonicalText\":\"」市吏甚怪太宰知之疾也，乃悚懼其所也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-65_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-65\",\"order\":1,\"canonicalText\":\"說六\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-66_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-66\",\"order\":1,\"canonicalText\":\"韓昭侯握爪而佯亡一爪，求之甚急，左右因割其爪而效之，昭侯以此察左右之誠不。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-67_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-67\",\"order\":1,\"canonicalText\":\"韓昭侯使騎於縣，使者報，昭侯問曰：「何見也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-67_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-67\",\"order\":2,\"canonicalText\":\"」對曰：「無所見也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-67_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-67\",\"order\":3,\"canonicalText\":\"」昭侯曰：「雖然何見？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-67_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-67\",\"order\":4,\"canonicalText\":\"」曰：「南門之外，有黃犢食苗道左者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-67_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-67\",\"order\":5,\"canonicalText\":\"」昭侯謂使者「毋敢洩吾所問於女」，乃下令曰：「當苗時，禁牛馬入人田中固有令，而吏不以為事，牛馬甚多入人田中，亟舉其數上之，不得，將重其罪。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-67_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-67\",\"order\":6,\"canonicalText\":\"」於是三鄉舉而上之，昭侯曰：「未盡也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-67_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-67\",\"order\":7,\"canonicalText\":\"」復往審之，乃得南門之外黃犢，吏以昭侯為明察，皆悚懼其所而不敢為非。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-68_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-68\",\"order\":1,\"canonicalText\":\"周主下令索曲杖，吏求之數日不能得，周主私使人求之，不移日而得之，乃謂吏曰：「吾知吏不事事也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-68_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-68\",\"order\":2,\"canonicalText\":\"曲杖甚易也，而吏不能得，我令人求之，不移日而得之，豈可謂忠哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-68_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-68\",\"order\":3,\"canonicalText\":\"」吏乃皆悚懼其所，以君為神明。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-69_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-69\",\"order\":1,\"canonicalText\":\"卜皮為縣令。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-69_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-69\",\"order\":2,\"canonicalText\":\"其御史汙穢，而有愛妾，卜皮乃使少庶子佯愛之以知御史陰情。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-70_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-70\",\"order\":1,\"canonicalText\":\"西門豹為鄴令，佯亡其車轄，令吏求之不能得，使人求之而得之家人屋間。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-71_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-71\",\"order\":1,\"canonicalText\":\"說七\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-72_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-72\",\"order\":1,\"canonicalText\":\"陽山君相衛，聞王之疑己也，乃偽謗樛豎以知之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-73_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-73\",\"order\":1,\"canonicalText\":\"淖齒聞齊王之惡己也，乃矯為秦使以知之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-74_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-74\",\"order\":1,\"canonicalText\":\"齊人有欲為亂者，恐王知之，因詐逐所愛者，令走王知之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-75_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-75\",\"order\":1,\"canonicalText\":\"子之相燕，坐而佯言曰：「走出門者何白馬也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-75_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-75\",\"order\":2,\"canonicalText\":\"」左右皆言不見。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-75_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-75\",\"order\":3,\"canonicalText\":\"有一人走追之，報曰：「有。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-75_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-75\",\"order\":4,\"canonicalText\":\"」子之以此知左右之誠信不。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-76_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-76\",\"order\":1,\"canonicalText\":\"有相與訟者，子產離之而無使得通辭，倒其言以告而知之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-77_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-77\",\"order\":1,\"canonicalText\":\"衛嗣公使人為客過關市，關市苛難之，因事關市以金，關吏乃舍之，嗣公為關吏曰：「某時有客過而所，與汝金，而汝因遣之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-30_p-77_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-30\",\"passageId\":\"han-fei-zi_ch-30_p-77\",\"order\":2,\"canonicalText\":\"」關市乃大恐，而以嗣公為明察。\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
